css:
.abk-salon {
  --abk-salon-bg: oklch(0.968 0.014 18);
  --abk-salon-ink: oklch(0.26 0.04 340);
  --abk-salon-accent: oklch(0.45 0.13 345);
  --abk-salon-gold: oklch(0.76 0.11 72);
  --abk-salon-card: color-mix(in oklch, var(--abk-salon-bg), white 62%);
  --abk-salon-line: color-mix(in oklch, var(--abk-salon-ink) 11%, transparent);
  --abk-salon-line2: color-mix(in oklch, var(--abk-salon-ink) 20%, transparent);
  --abk-salon-mute: color-mix(in oklch, var(--abk-salon-ink) 58%, var(--abk-salon-bg));
  --abk-salon-tint: color-mix(in oklch, var(--abk-salon-accent) 10%, var(--abk-salon-card));
  --abk-salon-tint2: color-mix(in oklch, var(--abk-salon-accent) 20%, var(--abk-salon-card));
  --abk-salon-on: oklch(0.985 0.008 18);
  --abk-salon-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-salon-spring: linear(0, .09 5%, .33 11%, .66 19%, .9 27%, 1.03 35%, 1.07 42%, 1.05 51%, 1.01 63%, .995 78%, 1);
  --abk-salon-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --abk-salon-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-salon-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-salon;
  overflow: clip; isolation: isolate; border-radius: 16px; border: 1px solid var(--abk-salon-line);
  background: var(--abk-salon-bg); color: var(--abk-salon-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--abk-salon-accent);
  -webkit-font-smoothing: antialiased;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-salon-accent); outline-offset: 2px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--abk-salon-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--abk-salon-line2); border-bottom-width: 2px; color: var(--abk-salon-mute); background: var(--abk-salon-card); }

  & .abk-salon-app {
    height: 100%; display: grid;
    grid-template: "top top top" auto "svc time visit" minmax(0, 1fr) / minmax(250px, 300px) minmax(0, 1fr) minmax(260px, 300px);
  }

  /* header */
  & .abk-salon-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 18px; border-bottom: 1px solid var(--abk-salon-line); }
  & .abk-salon-brand { display: flex; align-items: center; gap: 10px; flex: none;
    & svg { width: 30px; height: 30px; padding: 5px; border-radius: 50%; background: var(--abk-salon-accent); color: var(--abk-salon-on); stroke-width: 1.6; }
    & div { display: grid; line-height: 1.05; }
    & b { font: italic 600 22px/1 var(--abk-salon-serif); letter-spacing: -.01em; }
    & span { font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--abk-salon-mute); margin-top: 4px; }
  }
  & .abk-salon-steps { list-style: none; margin: 0 auto; padding: 0; display: flex; gap: 6px; counter-reset: s;
    & li { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; color: var(--abk-salon-mute); padding: 5px 12px 5px 6px; border-radius: 99px; transition: background .3s, color .3s; }
    & li + li::before { content: ""; width: 18px; height: 1px; background: var(--abk-salon-line2); margin: 0 4px 0 -12px; order: -1; }
    & i { font-style: normal; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; border: 1px solid var(--abk-salon-line2); font-variant-numeric: tabular-nums; }
  }
  &[data-step="pick"] .abk-salon-steps li[data-s="pick"],
  &[data-step="details"] .abk-salon-steps li[data-s="details"],
  &[data-step="done"] .abk-salon-steps li[data-s="done"] { color: var(--abk-salon-ink); background: var(--abk-salon-card);
    & i { background: var(--abk-salon-accent); border-color: var(--abk-salon-accent); color: var(--abk-salon-on); }
  }
  &[data-step="details"] .abk-salon-steps li[data-s="pick"] i,
  &[data-step="done"] .abk-salon-steps li:not([data-s="done"]) i { background: var(--abk-salon-tint2); border-color: transparent; color: var(--abk-salon-accent); }
  & .abk-salon-mine { display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 12px; border-radius: 10px; border: 1px solid var(--abk-salon-line2); font-size: 13px; font-weight: 600; flex: none;
    & svg { width: 17px; height: 17px; }
    & b { min-width: 20px; height: 20px; padding: 0 6px; border-radius: 99px; background: var(--abk-salon-ink); color: var(--abk-salon-on); font-size: 11px; display: grid; place-items: center; font-variant-numeric: tabular-nums; }
    &:hover { background: var(--abk-salon-card); }
    &[aria-expanded="true"] { background: var(--abk-salon-ink); color: var(--abk-salon-on); & b { background: var(--abk-salon-gold); color: var(--abk-salon-ink); } }
  }
  & .abk-salon-views { display: none; }

  /* services pane */
  & .abk-salon-services { grid-area: svc; display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--abk-salon-line); }
  & .abk-salon-phead { padding: 16px 16px 10px; display: grid; gap: 10px;
    & h2 { font: 600 clamp(19px, 2cqi, 23px)/1.1 var(--abk-salon-serif); letter-spacing: -.01em; }
  }
  & .abk-salon-search { display: flex; align-items: center; gap: 8px; height: 36px; padding: 0 8px 0 11px; border-radius: 10px; background: var(--abk-salon-card); border: 1px solid var(--abk-salon-line);
    & svg { width: 16px; height: 16px; color: var(--abk-salon-mute); flex: none; }
    & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 13.5px; }
    & input::-webkit-search-cancel-button { filter: grayscale(1); }
    &:focus-within { border-color: var(--abk-salon-accent); box-shadow: 0 0 0 3px var(--abk-salon-tint2); }
  }
  & .abk-salon-cats { display: flex; flex-wrap: wrap; gap: 4px; margin: 0 -2px; padding: 2px;
    & button { flex: none; height: 28px; padding: 0 10px; border-radius: 99px; font-size: 12.5px; font-weight: 600; color: var(--abk-salon-mute); border: 1px solid transparent; transition: background .2s, color .2s; }
    & button:hover { color: var(--abk-salon-ink); border-color: var(--abk-salon-line2); }
    & button[aria-selected="true"] { background: var(--abk-salon-ink); color: var(--abk-salon-on); }
  }
  & .abk-salon-menu { flex: 1; min-height: 0; overflow-y: auto; padding: 0 10px 14px; scrollbar-width: thin; overscroll-behavior: contain; }
  & .abk-salon-group { margin-top: 6px;
    & h4 { position: sticky; top: 0; z-index: 1; padding: 8px 6px 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--abk-salon-mute); background: linear-gradient(var(--abk-salon-bg) 75%, transparent); }
  }
  & .abk-salon-svc { position: relative; width: 100%; display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; text-align: left; padding: 10px 10px 11px 12px; border-radius: 12px; border: 1px solid transparent; transition: background .2s, border-color .2s;
    animation: abk-salon-rise .45s var(--abk-salon-ease) both; animation-delay: calc(var(--i, 0) * 28ms);
    & b { font-size: 14px; font-weight: 600; }
    & small { grid-column: 1; font-size: 12px; color: var(--abk-salon-mute); line-height: 1.35; }
    & .abk-salon-meta { grid-column: 1; display: flex; gap: 8px; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--abk-salon-ink); font-weight: 550; margin-top: 3px; }
    & .abk-salon-meta span + span::before { content: "·"; margin-right: 8px; color: var(--abk-salon-mute); }
    & .abk-salon-tick { grid-row: 1 / span 3; grid-column: 2; align-self: center; width: 24px; height: 24px; border-radius: 50%; border: 1.5px solid var(--abk-salon-line2); display: grid; place-items: center; transition: background .25s, border-color .25s, transform .4s var(--abk-salon-spring); }
    & .abk-salon-tick svg { width: 14px; height: 14px; stroke-width: 2.4; stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .3s .05s var(--abk-salon-ease); }
    & mark { background: color-mix(in oklch, var(--abk-salon-gold) 45%, transparent); color: inherit; border-radius: 3px; padding: 0 1px; }
    &:hover { background: var(--abk-salon-card); border-color: var(--abk-salon-line); }
    &[aria-checked="true"] { background: var(--abk-salon-tint); border-color: color-mix(in oklch, var(--abk-salon-accent) 35%, transparent);
      & .abk-salon-tick { background: var(--abk-salon-accent); border-color: var(--abk-salon-accent); color: var(--abk-salon-on); transform: scale(1.06); }
      & .abk-salon-tick svg { stroke-dashoffset: 0; }
    }
  }
  & .abk-salon-empty { padding: 26px 14px; text-align: center; color: var(--abk-salon-mute); font-size: 13px; display: grid; gap: 10px; justify-items: center;
    & svg { width: 28px; height: 28px; opacity: .6; }
    & button { font-weight: 650; color: var(--abk-salon-accent); text-decoration: underline; text-underline-offset: 3px; }
  }

  /* specialist + time */
  & .abk-salon-time { grid-area: time; min-height: 0; overflow-y: auto; padding: 16px 18px 18px; display: flex; flex-direction: column; gap: 14px; scrollbar-width: thin; overscroll-behavior: contain; }
  & .abk-salon-staff { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 6px; }
  & .abk-salon-person { position: relative; display: grid; justify-items: center; gap: 5px; padding: 10px 4px 9px; border-radius: 14px; border: 1px solid transparent; text-align: center; transition: background .2s, border-color .2s, opacity .2s;
    & .abk-salon-av { width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; font-weight: 700; font-size: 13.5px; letter-spacing: .02em; color: oklch(0.3 0.06 var(--h)); background: oklch(0.89 0.05 var(--h)); box-shadow: 0 0 0 2px var(--abk-salon-bg), 0 0 0 3px transparent; transition: box-shadow .25s, transform .45s var(--abk-salon-spring); }
    & .abk-salon-any { display: flex; }
    & .abk-salon-any i { width: 22px; height: 22px; margin-left: -8px; border-radius: 50%; border: 2px solid var(--abk-salon-bg); background: oklch(0.86 0.05 var(--h)); }
    & .abk-salon-any i:first-child { margin-left: 0; }
    & b { font-size: 12.5px; font-weight: 650; line-height: 1.1; }
    & small { font-size: 10.5px; color: var(--abk-salon-mute); line-height: 1.2; }
    &:hover:not([aria-disabled="true"]) { background: var(--abk-salon-card); }
    &[aria-checked="true"] { background: var(--abk-salon-card); border-color: var(--abk-salon-line2);
      & .abk-salon-av { box-shadow: 0 0 0 2px var(--abk-salon-card), 0 0 0 4px var(--abk-salon-accent); transform: scale(1.04); }
    }
    &[aria-disabled="true"] { opacity: .42; & .abk-salon-av { filter: grayscale(1); } }
  }
  & .abk-salon-dayrow { display: grid; grid-template-columns: 30px minmax(0, 1fr) 30px; gap: 6px; align-items: center; }
  & .abk-salon-wk { width: 30px; height: 56px; border-radius: 10px; display: grid; place-items: center; color: var(--abk-salon-mute);
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: var(--abk-salon-card); color: var(--abk-salon-ink); }
    &:disabled { opacity: .3; }
  }
  & .abk-salon-days { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 5px; }
  & .abk-salon-day { position: relative; display: grid; justify-items: center; gap: 1px; padding: 7px 2px 8px; border-radius: 12px; border: 1px solid var(--abk-salon-line); background: var(--abk-salon-card); transition: background .2s, color .2s, border-color .2s, transform .35s var(--abk-salon-spring);
    & small { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--abk-salon-mute); }
    & b { font: 600 19px/1.1 var(--abk-salon-serif); font-variant-numeric: tabular-nums lining-nums; }
    & .abk-salon-meter { width: 60%; height: 3px; border-radius: 3px; background: var(--abk-salon-line); overflow: hidden; margin-top: 3px; }
    & .abk-salon-meter i { display: block; height: 100%; width: calc(var(--f) * 100%); background: var(--abk-salon-accent); border-radius: inherit; transition: width .5s var(--abk-salon-ease); }
    &:hover:not(:disabled) { border-color: var(--abk-salon-line2); transform: translateY(-1px); }
    &[aria-checked="true"] { background: var(--abk-salon-ink); color: var(--abk-salon-on); border-color: var(--abk-salon-ink);
      & small { color: color-mix(in oklch, var(--abk-salon-on) 70%, transparent); }
      & .abk-salon-meter { background: color-mix(in oklch, var(--abk-salon-on) 22%, transparent); }
      & .abk-salon-meter i { background: var(--abk-salon-gold); }
    }
    &:disabled { opacity: .45; background: transparent; border-style: dashed; }
    &[data-today]::after { content: ""; position: absolute; top: 5px; right: 6px; width: 5px; height: 5px; border-radius: 50%; background: var(--abk-salon-gold); }
  }

  /* ribbon: one lane per capable specialist, ghost slides between them */
  & .abk-salon-ribbon { --abk-salon-lh: 24px; --abk-salon-gap: 6px; display: grid; grid-template-columns: 30px minmax(0, 1fr); gap: 4px 8px; padding: 12px 12px 8px; border-radius: 14px; background: var(--abk-salon-card); border: 1px solid var(--abk-salon-line); }
  & .abk-salon-labels { display: grid; gap: var(--abk-salon-gap); grid-auto-rows: var(--abk-salon-lh);
    & span { width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font-size: 9.5px; font-weight: 700; color: oklch(0.3 0.06 var(--h)); background: oklch(0.89 0.05 var(--h)); transition: box-shadow .3s; }
    & span[data-on] { box-shadow: 0 0 0 2px var(--abk-salon-card), 0 0 0 3.5px var(--abk-salon-accent); }
  }
  & .abk-salon-tracks { position: relative; display: grid; gap: var(--abk-salon-gap); grid-auto-rows: var(--abk-salon-lh); }
  & .abk-salon-lane { position: relative; border-radius: 6px; background: repeating-linear-gradient(90deg, transparent 0 calc(100% / 11 - 1px), var(--abk-salon-line) 0 calc(100% / 11)); box-shadow: inset 0 0 0 1px var(--abk-salon-line); overflow: hidden;
    & i { position: absolute; top: 3px; bottom: 3px; left: calc(var(--a) * 100%); width: calc(var(--w) * 100%); border-radius: 4px; background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--abk-salon-ink) 16%, transparent) 0 3px, color-mix(in oklch, var(--abk-salon-ink) 8%, transparent) 3px 6px); }
    & i[data-k="off"] { top: 0; bottom: 0; border-radius: 0; background: color-mix(in oklch, var(--abk-salon-ink) 7%, transparent); }
    & i[data-k="mine"] { background: color-mix(in oklch, var(--abk-salon-gold) 55%, transparent); }
  }
  & .abk-salon-now { position: absolute; top: -4px; bottom: -4px; left: calc(var(--a) * 100%); width: 2px; background: var(--abk-salon-gold); border-radius: 2px; z-index: 1;
    &::before { content: "now"; position: absolute; bottom: 100%; left: 50%; translate: -50% 0; font-size: 9px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: color-mix(in oklch, var(--abk-salon-gold) 60%, var(--abk-salon-ink)); }
  }
  & .abk-salon-ghost { position: absolute; z-index: 2; top: 0; left: 0; height: var(--abk-salon-lh); width: calc(var(--dur) / 660 * 100%); border-radius: 6px;
    translate: calc(var(--off) * 100%) calc(var(--lane) * (var(--abk-salon-lh) + var(--abk-salon-gap)));
    background: var(--abk-salon-accent); color: var(--abk-salon-on); box-shadow: 0 6px 16px -6px color-mix(in oklch, var(--abk-salon-accent) 70%, transparent);
    display: flex; align-items: center; justify-content: center; overflow: hidden; white-space: nowrap; font: 650 10.5px/1 var(--abk-salon-mono); font-variant-numeric: tabular-nums;
    transition: translate .55s var(--abk-salon-spring), width .35s var(--abk-salon-ease), opacity .25s, background .25s;
    &[data-preview] { background: color-mix(in oklch, var(--abk-salon-accent) 62%, var(--abk-salon-card)); }
    &[hidden] { display: flex; opacity: 0; }
  }
  & .abk-salon-axis { grid-column: 2; display: flex; justify-content: space-between; font: 10px/1 var(--abk-salon-mono); color: var(--abk-salon-mute); font-variant-numeric: tabular-nums; padding-top: 2px;
    & span { width: 0; display: flex; justify-content: center; }
  }
  & .abk-salon-slothead { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-top: 2px;
    & h3 { font: 600 16px/1.2 var(--abk-salon-serif); }
    & h3 small { font: 500 12.5px system-ui, sans-serif; color: var(--abk-salon-mute); margin-left: 6px; }
  }
  & .abk-salon-keys { display: flex; align-items: center; gap: 3px; font-size: 11px; color: var(--abk-salon-mute); white-space: nowrap; & kbd:nth-of-type(3) { margin-left: 8px; } }
  & .abk-salon-slots { display: grid; gap: 12px; }
  & .abk-salon-band { display: grid; grid-template-columns: 74px minmax(0, 1fr); gap: 8px; align-items: start;
    & > span { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--abk-salon-mute); padding-top: 10px; }
  }
  & .abk-salon-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(78px, 1fr)); gap: 6px; }
  & .abk-salon-slot { position: relative; height: 38px; border-radius: 10px; border: 1px solid var(--abk-salon-line2); background: var(--abk-salon-card); display: flex; align-items: center; justify-content: center; gap: 6px; font-weight: 600; font-size: 13.5px; font-variant-numeric: tabular-nums;
    transition: background .2s, color .2s, border-color .2s, transform .4s var(--abk-salon-spring);
    animation: abk-salon-rise .4s var(--abk-salon-ease) both; animation-delay: calc(var(--i, 0) * 14ms);
    & i { width: 16px; height: 16px; border-radius: 50%; font: 700 7.5px/16px system-ui, sans-serif; font-style: normal; text-align: center; color: oklch(0.3 0.06 var(--h)); background: oklch(0.88 0.05 var(--h)); }
    &:hover { border-color: var(--abk-salon-accent); transform: translateY(-1px); }
    &[aria-checked="true"] { background: var(--abk-salon-accent); border-color: var(--abk-salon-accent); color: var(--abk-salon-on); & i { box-shadow: 0 0 0 1.5px var(--abk-salon-on); } }
  }

  /* visit summary */
  & .abk-salon-visit { grid-area: visit; min-height: 0; overflow-y: auto; border-left: 1px solid var(--abk-salon-line); background: var(--abk-salon-card); display: flex; flex-direction: column; scrollbar-width: thin; }
  & .abk-salon-vbody { padding: 18px 18px 12px; display: grid; gap: 14px; align-content: start; flex: 1;
    & h2 { font: 600 clamp(19px, 2cqi, 23px)/1.1 var(--abk-salon-serif); display: flex; align-items: center; justify-content: space-between; }
  }
  & .abk-salon-vclose { display: none; }
  & .abk-salon-lines { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
  & .abk-salon-line { display: grid; grid-template-columns: minmax(0, 1fr) auto 26px; gap: 2px 8px; align-items: center; padding: 8px 0; border-bottom: 1px dashed var(--abk-salon-line2);
    animation: abk-salon-rise .35s var(--abk-salon-ease) both;
    & b { font-weight: 600; font-size: 13.5px; }
    & small { grid-column: 1; font-size: 12px; color: var(--abk-salon-mute); font-variant-numeric: tabular-nums; }
    & output { grid-row: 1 / span 2; grid-column: 2; font-weight: 650; font-variant-numeric: tabular-nums; }
    & button { grid-row: 1 / span 2; grid-column: 3; width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; color: var(--abk-salon-mute); }
    & button svg { width: 14px; height: 14px; }
    & button:hover { background: var(--abk-salon-tint); color: var(--abk-salon-accent); }
  }
  & .abk-salon-when { display: grid; grid-template-columns: 38px 1fr; gap: 2px 10px; align-items: center; padding: 12px; border-radius: 12px; background: var(--abk-salon-bg);
    & .abk-salon-av { grid-row: span 2; width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; font-weight: 700; font-size: 12.5px; color: oklch(0.3 0.06 var(--h)); background: oklch(0.89 0.05 var(--h)); }
