}

@keyframes abk-salon-rise { from { opacity: 0; translate: 0 6px; } }
@keyframes abk-salon-draw { to { stroke-dashoffset: 0; } }
@keyframes abk-salon-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }

