/* Fernhill Studio booking. Free start times are computed per specialist (shift hours minus a seeded day
   of existing appointments) at the summed length of the chosen services. The ribbon shows one lane per
   capable specialist; the ghost of your appointment slides to whichever lane and time a slot would book. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const hm = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const len = m => m >= 60 ? Math.floor(m / 60) + ' h' + (m % 60 ? ' ' + (m % 60) + ' min' : '') : m + ' min';
const IC = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>', arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>',
  info: '<circle cx="12" cy="12" r="8.5"/><path d="M12 11v5M12 8v.2"/>', search: '<circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.5 4.5"/>',
  clock: '<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>', back: '<path d="M19 12H5M11 6l-6 6 6 6"/>'
};
const svg = (k, cls) => '<svg viewBox="0 0 24 24" aria-hidden="true"' + (cls ? ' class="' + cls + '"' : '') + '>' + IC[k] + '</svg>';

const OPEN = 540, CLOSE = 1200, SPAN = CLOSE - OPEN;     // 09:00–20:00, the studio's day
const BASE = new Date(2026, 9, 8);                        // Thu 8 Oct 2026
const NOW = 640;                                          // 10:40 on day 0
const NDAYS = 14;
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dateOf = i => new Date(BASE.getFullYear(), BASE.getMonth(), BASE.getDate() + i);
const dayName = (i, long) => { const d = dateOf(i); return (i === 0 ? 'Today' : i === 1 ? 'Tomorrow' : WD[d.getDay()]) + (long ? ', ' + d.getDate() + ' ' + MON[d.getMonth()] : ''); };

const CATS = [['all', 'All'], ['cut', 'Cut & style'], ['colour', 'Colour'], ['care', 'Treatments'], ['skin', 'Skin']];
const SV = [
  { id: 'cutblow', cat: 'cut', name: 'Cut & blow-dry', min: 60, price: 68, d: 'Wash, precision cut and a smooth or textured finish.' },
  { id: 'fringe', cat: 'cut', name: 'Fringe & neckline tidy', min: 15, price: 18, d: 'A quick reshape between full cuts.' },
  { id: 'restyle', cat: 'cut', name: 'Restyle consultation & cut', min: 90, price: 92, d: 'For a big change: we sketch it first, then cut.' },
  { id: 'blow', cat: 'cut', name: 'Blow-dry & finish', min: 45, price: 42, d: 'Wash and a blow-dry that lasts the weekend.' },
  { id: 'roots', cat: 'colour', name: 'Root touch-up', min: 75, price: 72, d: 'Up to 2 cm of regrowth in permanent colour.' },
  { id: 'tint', cat: 'colour', name: 'Full head tint', min: 105, price: 96, d: 'One shade, roots to ends, finished with gloss.' },
  { id: 'balayage', cat: 'colour', name: 'Balayage', min: 150, price: 165, d: 'Hand-painted lightening, toned to finish.' },
  { id: 'gloss', cat: 'colour', name: 'Toner & gloss', min: 30, price: 38, d: 'Refreshes tone and adds shine between colours.' },
  { id: 'bond', cat: 'care', name: 'Bond repair treatment', min: 20, price: 28, d: 'Rebuilds strength after colour or heat styling.' },
  { id: 'scalp', cat: 'care', name: 'Scalp ritual', min: 30, price: 34, d: 'Exfoliation, pressure-point massage, cool rinse.' },
  { id: 'facial', cat: 'skin', name: 'Signature facial', min: 60, price: 78, d: 'Cleanse, enzyme peel, massage and a mask.' },
  { id: 'brow', cat: 'skin', name: 'Brow shape & tint', min: 30, price: 32, d: 'Wax, tidy and tint to frame the face.' }
];
const SVC = Object.fromEntries(SV.map(s => [s.id, s]));
const wk = (a, b, days) => Object.fromEntries(days.map(d => [d, [a, b]]));
const STAFF = [
  { id: 'maren', name: 'Maren Holt', ini: 'MH', role: 'Creative director', tier: 1.2, h: 345, does: ['cutblow', 'fringe', 'restyle', 'blow', 'roots', 'tint', 'balayage', 'gloss', 'bond', 'scalp'], hours: wk(540, 1050, [2, 3, 4, 5, 6]) },
  { id: 'theo', name: 'Theo Achterberg', ini: 'TA', role: 'Senior stylist', tier: 1.1, h: 215, does: ['cutblow', 'fringe', 'restyle', 'blow', 'bond', 'scalp'], hours: wk(660, 1200, [1, 2, 3, 4, 5]) },
  { id: 'ines', name: 'Ines Carvalho', ini: 'IC', role: 'Colourist', tier: 1.1, h: 75, does: ['blow', 'roots', 'tint', 'balayage', 'gloss', 'bond', 'scalp'], hours: wk(570, 1080, [0, 3, 4, 5, 6]) },
  { id: 'yusuf', name: 'Yusuf Demir', ini: 'YD', role: 'Stylist', tier: 1, h: 150, does: ['cutblow', 'fringe', 'blow', 'bond', 'scalp'], hours: wk(600, 1140, [1, 2, 4, 5, 6]) },
  { id: 'aiko', name: 'Aiko Lund', ini: 'AL', role: 'Skin therapist', tier: 1, h: 20, does: ['facial', 'brow'], hours: wk(540, 960, [1, 2, 3, 4, 6]) }
];
const STF = Object.fromEntries(STAFF.map(s => [s.id, s]));

/* seeded day of existing appointments per specialist */
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
const busyCache = new Map();
const extra = { 'aiko|9': [[690, 720, 'FH-4790']] };   /* your own appointments: key staff|day */
function busyOf(st, day) {
  const key = st.id + '|' + day;
  if (!busyCache.has(key)) {
    const h = st.hours[dateOf(day).getDay()], out = [];
    if (h) {
      const r = rng(STAFF.indexOf(st) * 977 + day * 131 + 17);
      let t = h[0] + (r() < .5 ? 0 : 15);
      while (t < h[1]) {
        if (r() < .4) { const l = [30, 45, 60, 60, 90][Math.floor(r() * 5)]; out.push([t, Math.min(t + l, h[1])]); t += l; }
        else t += [30, 45, 60, 75][Math.floor(r() * 4)];
      }
      if (!out.some(b => b[0] < 810 && b[1] > 780)) out.push([780, 810, 'break']);
    }
    /* never seed a client on top of an appointment that is already yours */
    busyCache.set(key, out.filter(b => !(extra[key] || []).some(m => b[0] < m[1] && b[1] > m[0])));
  }
  return busyCache.get(key).concat((extra[key] || []).map(b => [b[0], b[1], 'mine']));
}
function freeStarts(st, day, need) {
  const h = st.hours[dateOf(day).getDay()];
  if (!h || !need) return [];
  const busy = busyOf(st, day), out = [];
  let t = h[0];
  if (day === 0) t = Math.max(t, Math.ceil((NOW + 5) / 15) * 15);
  for (; t + need <= h[1]; t += 15) if (!busy.some(b => t < b[1] && t + need > b[0])) out.push(t);
  return out;
}

/* ── state ── */
const S = {
  cat: 'all', q: '', sel: ['cutblow', 'bond'], staff: 'any', day: 0, week: 0,
  slot: null, preview: null, view: 'services', step: 'pick',
  form: { name: '', phone: '', email: '', notes: '', remind: true }, errors: {},
  mine: [{ ref: 'FH-4790', svc: ['brow'], staff: 'aiko', day: 9, t: 690, price: 32, min: 30 }]
};
let undoFn = null, toastT = 0, refN = 4821;

const need = () => S.sel.reduce((n, id) => n + SVC[id].min, 0);
const capable = st => S.sel.length > 0 && S.sel.every(id => st.does.includes(id));
const priceFor = (st, id) => Math.round(SVC[id].price * (st ? st.tier : 1));
const missing = st => S.sel.filter(id => !st.does.includes(id)).map(id => SVC[id].name);

/* slots for a day: [{t, staff}] — "any" picks the first free capable specialist, lowest tier first */
function slotsFor(day) {
  const n = need();
  if (!n) return [];
  if (S.staff !== 'any') { const st = STF[S.staff]; return capable(st) ? freeStarts(st, day, n).map(t => ({ t, st })) : []; }
  const pool = STAFF.filter(capable).sort((a, b) => a.tier - b.tier), map = new Map();
  pool.forEach(st => freeStarts(st, day, n).forEach(t => { if (!map.has(t)) map.set(t, st); }));
  return [...map.entries()].sort((a, b) => a[0] - b[0]).map(([t, st]) => ({ t, st }));
}
