/* ── events ── */
root.addEventListener('click', e => {
  const t = e.target.closest('button');
  if (!t || !root.contains(t)) return;
  if (t.getAttribute('aria-disabled') === 'true') { toast(t.title || 'Not available'); return; }
  const act = t.dataset.act;
  if (t.dataset.cat) { S.cat = t.dataset.cat; renderCats(); renderMenu(); return; }
  if (t.dataset.svc) { toggleService(t.dataset.svc); return; }
  if (t.dataset.remove) { const id = t.dataset.remove; toggleService(id); toast(SVC[id].name + ' removed', () => toggleService(id)); return; }
  if (t.dataset.staff) {
    flipSlots(() => { S.staff = t.dataset.staff; S.preview = null; revalidate(); render(['time', 'visit']); });
    return;
  }
  if (t.dataset.day && !act) { setDay(+t.dataset.day); return; }
  if (t.dataset.t) { pickSlot(+t.dataset.t, t.dataset.st); return; }
  if (t.dataset.v) { S.view = t.dataset.v; syncChrome(); renderBar(); return; }
  if (t.dataset.cancel) {
    const ref = t.dataset.cancel, b = S.mine.find(x => x.ref === ref), key = b.staff + '|' + b.day;
    S.mine = S.mine.filter(x => x.ref !== ref);
    const kept = extra[key] ? extra[key].filter(x => x[2] !== ref) : null;
    const prev = extra[key];
    if (kept) extra[key] = kept;
    render();
    toast('Cancelled ' + b.svc.map(id => SVC[id].name).join(' + '), () => { S.mine.push(b); if (prev) extra[key] = prev; render(); });
    return;
  }
  switch (act) {
    case 'mine': openDrawer(!$('[data-drawer]').hasAttribute('data-open')); break;
    case 'close': openDrawer(false); $('[data-act="mine"]').focus(); break;
    case 'wk': {
      const w = Math.max(0, Math.min(1, S.week + +t.dataset.d));
      let i = w * 7;
      while (i < w * 7 + 6 && !slotsFor(i).length) i++;
      setDay(i); break;
    }
    case 'jump': setDay(+t.dataset.day); break;
    case 'clearq': S.q = ''; $('[data-q]').value = ''; renderMenu(); break;
    case 'toservices': S.view = 'services'; syncChrome(); renderBar(); $('[data-q]').focus(); break;
    case 'continue': if (S.slot) { S.step = 'details'; S.view = 'visit'; render(['visit']); const f = $('#abk-salon-name'); if (f) f.focus({ preventScroll: true }); } break;
    case 'back': S.step = 'pick'; S.errors = {}; render(['visit']); break;
