        else if (S.slot) { S.step = 'details'; render(['visit']); const f = $('#abk-salon-name'); if (f) f.focus({ preventScroll: true }); }
      } else { S.view = root.clientWidth < 760 && S.view === 'services' ? 'time' : 'visit'; syncChrome(); renderBar(); }
      break;
    case 'vclose': S.view = 'time'; syncChrome(); renderBar(); break;
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); } $('.abk-salon-toast').removeAttribute('data-open'); break;
    case 'cal': toast('Added to your calendar: Fernhill Studio, ' + $('[data-done] dd').textContent); break;
