  if ((next && S.preview && next.t === S.preview.t && next.st === S.preview.st) || (!next && !S.preview)) return;
  S.preview = next; placeGhost();
};
root.addEventListener('pointerover', e => preview(e.target));
root.addEventListener('pointerleave', () => preview(null));
root.addEventListener('focusin', e => preview(e.target));
$('[data-slots]').addEventListener('pointerleave', () => preview(null));

root.addEventListener('keydown', e => {
  const typing = e.target.matches('input, textarea');
  if (e.key === 'Escape') {
    if ($('[data-drawer]').hasAttribute('data-open')) { openDrawer(false); $('[data-act="mine"]').focus(); e.preventDefault(); return; }
    if ($('[data-done]').hasAttribute('data-open')) { resetAfterDone(); e.preventDefault(); return; }
    if (typing && e.target.matches('[data-q]') && S.q) { S.q = ''; e.target.value = ''; renderMenu(); return; }
  }
  if (typing) return;
  if (e.key === '/') { e.preventDefault(); if (S.view !== 'services') { S.view = 'services'; syncChrome(); renderBar(); } $('[data-q]').focus(); return; }
  if (e.key === '[' || e.key === ']') {
    e.preventDefault();
    const d = e.key === ']' ? 1 : -1;
    let i = S.day + d;
    while (i >= 0 && i < NDAYS && !slotsFor(i).length) i += d;
    if (i >= 0 && i < NDAYS) setDay(i); else toast('No more days with a free ' + len(need()) + ' opening that way');
    return;
  }
  const slot = e.target.closest && e.target.closest('.abk-salon-slot');
  if (slot && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
    e.preventDefault();
    const all = $$('.abk-salon-slot'), i = all.indexOf(slot);
    const cols = Math.max(1, Math.round(slot.parentElement.getBoundingClientRect().width / (slot.getBoundingClientRect().width + 6)));
    const j = e.key === 'Home' ? 0 : e.key === 'End' ? all.length - 1 : i + ({ ArrowLeft: -1, ArrowRight: 1, ArrowUp: -cols, ArrowDown: cols }[e.key]);
