    let i = S.day + d;
    while (i >= 0 && i < NDAYS && !slotsFor(i).length) i += d;
    if (i >= 0 && i < NDAYS) { setDay(i); const b = $('.abk-salon-day[data-day="' + i + '"]'); if (b) b.focus(); }
  }
});

new ResizeObserver(() => { if (!root.isConnected) return; renderBar(); }).observe(root);

/* initial: preselect the first afternoon opening today so the ribbon has something to show */
(() => {
