  }
}

@keyframes abk-classes-in { from { opacity: 0; transform: translateY(5px); } }

js:
/* Tensile Studio timetable. Every capacity ring is a registered @property (--abk-classes-fill), so a
   booking, a waitlist join or a promotion animates the conic fill instead of jumping. Cancelling a full
   class hands your spot to the head of the waitlist; the dot flies from the queue to the roster. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const hm = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const IC = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>', info: '<circle cx="12" cy="12" r="8.5"/><path d="M12 11v5M12 8v.2"/>',
  cal: '<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M9 3v4M15 3v4"/>', queue: '<path d="M4 7h11M4 12h11M4 17h7"/><path d="m17 14 3 3-3 3"/>',
  arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>', mat: '<rect x="3" y="9" width="18" height="6" rx="3"/><path d="M7 9v6"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const MON0 = new Date(2026, 9, 12);                 /* Mon 12 Oct 2026 */
const NOW = { w: 0, d: 2, m: 730 };                 /* Wed 14 Oct, 12:10 */
const DN = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const MN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dateOf = (w, d) => new Date(MON0.getFullYear(), MON0.getMonth(), MON0.getDate() + w * 7 + d);
const absMin = (w, d, m) => (w * 7 + d) * 1440 + m;
const NOWABS = absMin(NOW.w, NOW.d, NOW.m);
const PACK = 10, LAMBDA = 1.6;

const TYPES = {
  reformer: { name: 'Reformer', h: 32, cap: 10 }, barre: { name: 'Barre', h: 352, cap: 16 },
  mat: { name: 'Mat', h: 145, cap: 18 }, strength: { name: 'Strength', h: 255, cap: 14 }, stretch: { name: 'Stretch', h: 80, cap: 18 }
};
const COACH = {
  noor: { name: 'Noor Haddad', ini: 'NH', h: 32, bio: 'Reformer lead · teaching since 2017' },
  jonas: { name: 'Jonas Brekke', ini: 'JB', h: 220, bio: 'Physio-trained · rehab and posture' },
  lea: { name: 'Léa Fontaine', ini: 'LF', h: 352, bio: 'Former dancer · barre and mat' },
  rafa: { name: 'Rafa Okonkwo', ini: 'RO', h: 255, bio: 'Strength coach · loves a tempo count' },
  ama: { name: 'Ama Lindqvist', ini: 'AL', h: 80, bio: 'Mobility and breath work' }
};
const DESC = {
  'Reformer Flow': 'A flowing full-body sequence on the reformer. Springs are set for you; expect a long footwork section and a slow finish.',
  'Reformer Strength': 'Heavier springs, fewer reps, longer holds. Glutes, back and the deep core do most of the work.',
  'Reformer Foundations': 'New to the reformer? Learn the carriage, the straps and the springs, at a pace that leaves room for questions.',
  'Reformer Express': 'Thirty-five minutes, no fluff. Back at your desk by 13:00.',
  'Jumpboard Cardio': 'The jumpboard goes on and the heart rate goes up. Low impact, high sweat.',
  'Barre Burn': 'Small ranges, big shake. Ballet barre work for legs and seat, finished on the mat.',
  'Barre Express': 'A tight 30-minute barre for the lunch break.',
  'Mat Pilates': 'Classical mat repertoire with small props. The hundred is non-negotiable.',
  'Mat Express': 'Thirty minutes of mat work: core, spine and breath.',
  'Strength Circuit': 'Kettlebells, sliders and bands in timed stations. Bring water.',
  'Stretch & Release': 'Long holds, foam rollers and a guided wind-down. Ideal after a heavy week.'
};
/* weekday template: [start, minutes, type, name, coach, room, level] */
const T = [
  [[420, 50, 'reformer', 'Reformer Flow', 'noor', 'Studio A', 'All levels'], [570, 50, 'mat', 'Mat Pilates', 'jonas', 'Studio B', 'All levels'], [735, 30, 'barre', 'Barre Express', 'lea', 'Studio B', 'All levels'], [1080, 50, 'reformer', 'Reformer Strength', 'noor', 'Studio A', 'Intermediate'], [1155, 45, 'stretch', 'Stretch & Release', 'ama', 'Studio B', 'All levels']],
  [[405, 45, 'strength', 'Strength Circuit', 'rafa', 'Studio B', 'All levels'], [480, 55, 'reformer', 'Reformer Foundations', 'lea', 'Studio A', 'Beginner'], [735, 35, 'reformer', 'Reformer Express', 'jonas', 'Studio A', 'All levels'], [1050, 50, 'barre', 'Barre Burn', 'lea', 'Studio B', 'All levels'], [1125, 50, 'reformer', 'Reformer Flow', 'noor', 'Studio A', 'All levels']],
  [[420, 50, 'reformer', 'Reformer Strength', 'jonas', 'Studio A', 'Intermediate'], [570, 50, 'barre', 'Barre Burn', 'lea', 'Studio B', 'All levels'], [735, 30, 'mat', 'Mat Express', 'ama', 'Studio B', 'All levels'], [1080, 45, 'reformer', 'Jumpboard Cardio', 'rafa', 'Studio A', 'Intermediate'], [1155, 45, 'stretch', 'Stretch & Release', 'ama', 'Studio B', 'All levels']],
  [[405, 45, 'strength', 'Strength Circuit', 'rafa', 'Studio B', 'All levels'], [480, 50, 'reformer', 'Reformer Flow', 'jonas', 'Studio A', 'All levels'], [735, 35, 'reformer', 'Reformer Express', 'noor', 'Studio A', 'All levels'], [1050, 50, 'mat', 'Mat Pilates', 'jonas', 'Studio B', 'All levels'], [1125, 50, 'reformer', 'Reformer Flow', 'noor', 'Studio A', 'All levels']],
  [[420, 50, 'reformer', 'Reformer Strength', 'noor', 'Studio A', 'Intermediate'], [570, 45, 'stretch', 'Stretch & Release', 'ama', 'Studio B', 'All levels'], [735, 30, 'barre', 'Barre Express', 'lea', 'Studio B', 'All levels'], [1050, 45, 'strength', 'Strength Circuit', 'rafa', 'Studio B', 'All levels']],
  [[510, 50, 'reformer', 'Reformer Flow', 'noor', 'Studio A', 'All levels'], [600, 50, 'barre', 'Barre Burn', 'lea', 'Studio B', 'All levels'], [690, 55, 'reformer', 'Reformer Foundations', 'jonas', 'Studio A', 'Beginner']],
  [[540, 60, 'stretch', 'Stretch & Release', 'ama', 'Studio B', 'All levels'], [630, 50, 'reformer', 'Reformer Flow', 'jonas', 'Studio A', 'All levels'], [720, 50, 'mat', 'Mat Pilates', 'lea', 'Studio B', 'All levels']]
];
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

/* all class instances for two published weeks */
const C = {};
for (let w = 0; w < 2; w++) T.forEach((day, d) => day.forEach((row, i) => {
  const [m, dur, type, name, coach, room, level] = row, cap = TYPES[type].cap, r = rng(w * 1000 + d * 37 + i * 7 + 3);
  const hot = type === 'reformer' && (m >= 1050 || d >= 5 || m <= 420);
  const booked = hot ? cap : Math.max(2, Math.min(cap, Math.round(cap * (.38 + r() * .58))));
  const wait = booked === cap ? (hot ? 1 + Math.floor(r() * 4) : 0) : 0;
  const id = w + '-' + d + '-' + i;
  C[id] = { id, w, d, i, m, dur, type, name, coach, room, level, cap, booked, wait, me: null, pos: 0, auto: true };
}));
const me = (id, state, pos) => { const c = C[id]; c.me = state; if (state === 'wait') { c.pos = pos; } };
me('0-0-3', 'attended'); me('0-1-1', 'attended'); me('0-3-4', 'booked'); me('0-5-0', 'booked');
me('0-2-3', 'wait', 2); C['0-2-3'].wait = 4;
const HISTORY = [{ label: 'Reformer Flow', date: 'Sat 10 Oct', k: 'att' }];

const S = { w: 0, day: NOW.d, sel: '0-2-3', types: new Set(), open: false, view: 'week', lateArm: null };
let undoFn = null, toastT = 0;

const isPast = c => absMin(c.w, c.d, c.m) <= NOWABS;
const isLate = c => absMin(c.w, c.d, c.m) - NOWABS < 12 * 60;
const state = c => c.me === 'booked' && isPast(c) ? 'attended' : c.me || (isPast(c) ? 'past' : null);
const left = c => c.cap - c.booked;
const credits = () => {
  const used = HISTORY.length + Object.values(C).filter(c => c.me === 'booked' || c.me === 'attended').length;
  const att = HISTORY.length + Object.values(C).filter(c => state(c) === 'attended').length;
  return { used, att, bk: used - att, left: PACK - used };
};
/* P(at least `pos` late cancellations) with a Poisson rate of LAMBDA per full class */
const odds = pos => { let p = 0, term = Math.exp(-LAMBDA); for (let k = 0; k < pos; k++) { p += term; term *= LAMBDA / (k + 1); } return Math.max(0, 1 - p); };
const visible = c => (!S.types.size || S.types.has(c.type)) && (!S.open || (!isPast(c) && (left(c) > 0 || c.me)));
const dayLabel = (w, d) => { const dt = dateOf(w, d); return DN[d] + ' ' + dt.getDate() + ' ' + MN[dt.getMonth()]; };

/* ── render ── */
function ringHTML(c, big) {
  const l = left(c);
  return '<span class="abk-classes-ring"' + (l <= 0 ? ' data-full' : '') + ' style="--abk-classes-fill:' + (c.booked / c.cap).toFixed(3) + '"><span>' + (big ? c.booked + '/' + c.cap : l > 0 ? l : c.wait ? '+' + c.wait : '0') + '</span></span>';
}
function cardLine(c) {
  const st = state(c), coach = COACH[c.coach].name.split(' ')[0], l = left(c);
  return st === 'attended' ? 'Attended' : st === 'past' ? 'Ended' : st === 'booked' ? 'You’re in · ' + coach : st === 'wait' ? 'Waitlist #' + c.pos + ' of ' + c.wait : l > 0 ? coach + ' · ' + l + ' left' : 'Full · ' + c.wait + ' waiting';
}
function cardInner(c) {
  return '<time>' + hm(c.m) + '</time><b>' + c.name + '</b><small>' + cardLine(c) + '</small>' + ringHTML(c);
}
function cardAttrs(card, c) {
  const st = state(c);
  if (st) card.dataset.state = st; else card.removeAttribute('data-state');
  card.setAttribute('aria-label', dayLabel(c.w, c.d) + ' ' + hm(c.m) + ', ' + c.name + ', ' + (st || (left(c) > 0 ? left(c) + ' spots left' : 'full')));
  if (S.sel === c.id) card.setAttribute('aria-current', 'true'); else card.removeAttribute('aria-current');
}
function renderWeek() {
  const tt = $('[data-tt]'), bands = [['Morning', 0, 660], ['Midday', 660, 960], ['Evening', 960, 1440]];
  let html = '<div class="abk-classes-dh" aria-hidden="true"></div>';
  for (let d = 0; d < 7; d++) {
    const dt = dateOf(S.w, d), today = S.w === NOW.w && d === NOW.d, past = S.w === NOW.w && d < NOW.d;
    html += '<div class="abk-classes-dh"' + (today ? ' data-today' : '') + (past ? ' data-past' : '') + ' data-d="' + d + '"><small>' + DN[d] + '</small><b>' + dt.getDate() + '</b></div>';
  }
  let n = 0;
  bands.forEach(([name, a, b]) => {
    html += '<div class="abk-classes-band">' + name + '</div>';
    for (let d = 0; d < 7; d++) {
      const list = Object.values(C).filter(c => c.w === S.w && c.d === d && c.m >= a && c.m < b);
      html += '<div class="abk-classes-cell" data-d="' + d + '"' + (S.w === NOW.w && d === NOW.d ? ' data-today' : '') + '>' +
