}
function renderSide() {
  const side = $('[data-side]'), c = C[S.sel];
  if (!c) { side.innerHTML = '<div class="abk-classes-empty">' + svg('mat') + '<b>Pick a class</b><p>Tap any class to see who’s teaching, how full it is and whether a waitlist spot is likely to clear.</p></div>'; return; }
  const st = state(c), coach = COACH[c.coach], k = credits(), l = left(c), late = isLate(c) && !isPast(c);
  const seats = Array.from({ length: c.cap }, (_, i) => {
    const mine = c.me === 'booked' || c.me === 'attended';
    const k2 = i < c.booked ? (mine && i === c.booked - 1 ? 'me' : 't') : '';
