  } else {
    actions = '<button type="button" class="abk-classes-btn" data-act="wait">' + svg('queue') + 'Join waitlist as #' + (c.wait + 1) + ' <kbd>B</kbd></button><p class="abk-classes-policy">' + svg('info') + '<span>No credit is held while you wait. If a spot opens, one credit is used and we text you.</span></p>';
  }
  const dt = dateOf(c.w, c.d);
  side.innerHTML = '<div class="abk-classes-detail" style="--h:' + TYPES[c.type].h + '">' +
    '<button type="button" class="abk-classes-close" data-act="closeside" aria-label="Close details">' + svg('x') + '</button>' +
    '<header><span class="abk-classes-type"><i></i>' + TYPES[c.type].name + ' · ' + c.level + '</span><h3>' + c.name + '</h3>' +
    '<span class="abk-classes-when">' + DN[c.d] + ' ' + dt.getDate() + ' ' + MN[dt.getMonth()] + ' · ' + hm(c.m) + '–' + hm(c.m + c.dur) + ' <span>· ' + c.room + '</span></span></header>' +
    '<p style="font-size:13px;color:var(--abk-classes-mute)">' + DESC[c.name] + '</p>' +
    '<div class="abk-classes-cap">' + ringHTML(c, true) + '<p><b>' + (l > 0 ? l + ' of ' + c.cap + ' spots left' : 'Full') + '</b><br>' + c.booked + ' booked' + (c.wait ? ' · ' + c.wait + ' on the waitlist' : '') + '</p></div>' +
    '<div class="abk-classes-seats" aria-label="' + c.booked + ' of ' + c.cap + ' places taken">' + seats + '</div>' + queue + odd +
    '<div class="abk-classes-who" style="--h:' + coach.h + '"><span>' + coach.ini + '</span><b>' + coach.name + '</b><small>' + coach.bio + '</small></div>' +
    '<div class="abk-classes-actions">' + actions + '</div>' +
    (st === 'booked' || (!st && l > 0) ? '<p class="abk-classes-policy">' + svg('info') + '<span>' + (late ? 'Starts in under 12 hours: cancelling now forfeits the credit.' : 'Free cancellation until ' + hm(c.m) + ' the day before.') + '</span></p>' : '') +
    '</div>';
}
function nextWeekBtn(c) {
  const nx = c.w === 0 ? C['1-' + c.d + '-' + c.i] : null;
  return nx ? '<button type="button" class="abk-classes-btn" data-tone="ghost" data-act="next" data-id="' + nx.id + '">Same class next week ' + svg('arrow') + '</button>' : '';
}
function renderMine() {
  const rows = Object.values(C).filter(c => c.me).sort((a, b) => absMin(a.w, a.d, a.m) - absMin(b.w, b.d, b.m));
  const up = rows.filter(c => !isPast(c)), done = rows.filter(c => isPast(c));
  const row = (c, i) => {
    const dt = dateOf(c.w, c.d), st = state(c);
    return '<button type="button" class="abk-classes-row" data-open="' + c.id + '" style="--i:' + i + '"><span class="abk-classes-d"><small>' + DN[c.d] + '</small><b>' + dt.getDate() + '</b></span><strong>' + c.name + '</strong>' +
      '<em' + (st === 'wait' ? ' data-k="wait"' : st === 'attended' ? ' data-k="att"' : '') + '>' + (st === 'wait' ? '#' + c.pos + ' waitlist' : st === 'attended' ? 'Attended' : 'Booked') + '</em><span>' + hm(c.m) + ' · ' + COACH[c.coach].name + ' · ' + c.room + '</span></button>';
  };
  const k = credits();
  const ledger = [['10-class pack · bought 1 Oct', '+' + PACK]].concat(
    HISTORY.map(h => [h.label + ' · ' + h.date, '−1']),
    rows.filter(c => c.me === 'booked' || c.me === 'attended').map(c => [c.name + ' · ' + dayLabel(c.w, c.d) + (state(c) === 'booked' ? ' (booked)' : ''), '−1']));
  $('[data-mine]').innerHTML =
    '<section class="abk-classes-sec"><h3><span>Upcoming</span><span>' + up.length + '</span></h3>' + (up.length ? up.map(row).join('') : '<p class="abk-classes-policy">Nothing booked. The timetable is a click away.</p>') + '</section>' +
    '<section class="abk-classes-sec"><h3><span>Attended</span><span>' + (done.length + HISTORY.length) + '</span></h3>' + done.map(row).join('') + '</section>' +
    '<section class="abk-classes-sec"><h3><span>Credit ledger</span><span>pack expires 30 Nov</span></h3><div class="abk-classes-ledger">' +
    ledger.map(r => '<div><span>' + r[0] + '</span><span>' + r[1] + '</span></div>').join('') + '<div data-total><span>Credits left</span><span>' + k.left + '</span></div></div></section>';
