function setView(v) {
  S.view = v;
  $('.abk-classes-app').dataset.view = v;
  $$('.abk-classes-tabs [role="tab"]').forEach(b => b.setAttribute('aria-selected', String(b.dataset.view === v)));
  if (v === 'mine') renderMine();
}
function select(id, focus) {
  const prev = S.sel;
  S.sel = id; S.lateArm = null;
  const c = C[id];
  if (c.w !== S.w) { S.w = c.w; S.day = c.d; renderWeek(); }
  [prev, id].forEach(x => { const card = $('.abk-classes-card[data-id="' + x + '"]'); if (card) cardAttrs(card, C[x]); });
  if (S.day !== c.d) { S.day = c.d; renderStrip(); }
  renderSide();
  $('.abk-classes-app').toggleAttribute('data-open', true);
  if (focus) { const card = $('.abk-classes-card[data-id="' + id + '"]'); if (card) card.focus(); }
}
function toast(msg, undo) {
  const t = $('.abk-classes-toast');
  $('[data-msg]', t).textContent = msg;
  undoFn = undo || null;
  $('[data-act="undo"]', t).hidden = !undo;
  t.setAttribute('data-open', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => t.removeAttribute('data-open'), 4500);
}
const snap = id => JSON.stringify(C[id]);
const restore = (id, s) => { Object.assign(C[id], JSON.parse(s)); refresh(id); };
function refresh(id) { updateCard(id); renderWallet(); renderSide(); if (S.view === 'mine') renderMine(); applyFilter(false); }

/* the promoted member's dot flies from the head of the queue into the place you left */
function flyPromotion(fromRect) {
  if (RM.matches || !fromRect) return;
  const to = $('.abk-classes-seats [data-k="new"]');
  if (!to) return;
  const rb = root.getBoundingClientRect(), tr = to.getBoundingClientRect();
  const dot = document.createElement('span');
  dot.style.cssText = 'position:absolute;z-index:50;left:' + (fromRect.left - rb.left) + 'px;top:' + (fromRect.top - rb.top) + 'px;width:' + fromRect.width + 'px;height:' + fromRect.height + 'px;border-radius:50%;background:var(--abk-classes-ok);pointer-events:none';
  root.appendChild(dot);
  to.style.opacity = '0';
  const dx = tr.left - fromRect.left + (tr.width - fromRect.width) / 2, dy = tr.top - fromRect.top + (tr.height - fromRect.height) / 2;
  dot.animate([{ transform: 'none', borderRadius: '50%' }, { transform: 'translate(' + dx * .5 + 'px,' + (dy * .5 - 40) + 'px) scale(1.15)', offset: .5 }, { transform: 'translate(' + dx + 'px,' + dy + 'px) scale(' + tr.width / fromRect.width + ')', borderRadius: '4px' }],
    { duration: 720, easing: 'cubic-bezier(.3,.7,.2,1)' }).onfinish = () => { dot.remove(); to.style.opacity = ''; };
}

function act(a, el) {
  const c = C[S.sel];
  if (!c && ['book', 'wait', 'cancel', 'leave', 'auto', 'cal', 'keep'].includes(a)) return;
  switch (a) {
    case 'book': {
      if (state(c) || left(c) <= 0) return;
      if (credits().left <= 0) { toast('No credits left in your pack'); return; }
      const s = snap(c.id);
      c.booked++; c.me = 'booked';
      refresh(c.id);
      toast('Booked ' + c.name + ', ' + DN[c.d] + ' ' + hm(c.m) + ' · 1 credit used', () => restore(c.id, s));
      break;
    }
    case 'wait': {
      if (state(c)) return;
      const s = snap(c.id);
      c.wait++; c.me = 'wait'; c.pos = c.wait; c.auto = true;
      refresh(c.id);
      toast('You’re #' + c.pos + ' on the waitlist', () => restore(c.id, s));
      break;
    }
    case 'cancel': {
      if (state(c) !== 'booked') return;
      if (isLate(c) && !el.dataset.confirm) { S.lateArm = c.id; renderSide(); const b = $('[data-confirm]'); if (b) b.focus(); return; }
      const s = snap(c.id), late = isLate(c);
      const head = c.wait ? $('.abk-classes-queue li') : null, from = head ? head.getBoundingClientRect() : null;
      c.me = null;
      if (late) HISTORY.push({ label: c.name + ' (late cancel)', date: dayLabel(c.w, c.d), k: 'late', id: c.id });
      if (c.wait) c.wait--; else c.booked--;
      S.lateArm = null;
      refresh(c.id);
      if (from) { const seat = $$('.abk-classes-seats i')[c.booked - 1]; if (seat) seat.dataset.k = 'new'; flyPromotion(from); }
      toast((late ? 'Late cancel: credit forfeited' : 'Cancelled, credit returned') + (from ? ' · waitlist #1 moved in' : ''), () => { if (late) HISTORY.pop(); restore(c.id, s); });
      break;
    }
    case 'keep': S.lateArm = null; renderSide(); break;
    case 'leave': {
      if (state(c) !== 'wait') return;
      const s = snap(c.id);
      c.wait--; c.me = null; c.pos = 0;
      refresh(c.id);
      toast('Left the waitlist for ' + c.name, () => restore(c.id, s));
      break;
    }
    case 'auto': c.auto = !c.auto; el.setAttribute('aria-checked', String(c.auto)); toast(c.auto ? 'We’ll book you in automatically' : 'We’ll text you first and hold the spot for 30 minutes'); break;
    case 'cal': toast('Added to calendar: ' + c.name + ', ' + dayLabel(c.w, c.d) + ' ' + hm(c.m)); break;
    case 'next': select(el.dataset.id, true); break;
    case 'closeside': $('.abk-classes-app').removeAttribute('data-open'); { const card = $('.abk-classes-card[data-id="' + S.sel + '"]'); if (card) card.focus(); } break;
    case 'week': {
      const w = Math.max(0, Math.min(1, S.w + +el.dataset.d));
      if (w === S.w) return;
      S.w = w; renderWeek(); break;
    }
    case 'open': S.open = !S.open; $('[data-act="open"]').setAttribute('aria-checked', String(S.open)); applyFilter(true); break;
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); } $('.abk-classes-toast').removeAttribute('data-open'); break;
  }
}

root.addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b || !root.contains(b)) return;
  if (b.dataset.id && b.classList.contains('abk-classes-card')) { select(b.dataset.id); return; }
  if (b.dataset.type) {
    const t = b.dataset.type;
    S.types.has(t) ? S.types.delete(t) : S.types.add(t);
    b.setAttribute('aria-pressed', String(S.types.has(t)));
    applyFilter(true);
    return;
  }
  if (b.dataset.view) { setView(b.dataset.view); return; }
  if (b.dataset.day) { S.day = +b.dataset.day; renderStrip(); return; }
  if (b.dataset.open) { select(b.dataset.open); $$('.abk-classes-row').forEach(r => r.toggleAttribute('aria-current', r.dataset.open === S.sel)); return; }
  if (b.dataset.act) act(b.dataset.act, b);
});

/* arrows move to the nearest visible card in that direction */
function nearest(from, key) {
  const r0 = from.getBoundingClientRect(), cx = r0.left + r0.width / 2, cy = r0.top + r0.height / 2;
  let best = null, bd = Infinity;
  $$('.abk-classes-card').filter(c => !c.hidden && c !== from && c.offsetParent).forEach(c => {
    const r = c.getBoundingClientRect(), x = r.left + r.width / 2, y = r.top + r.height / 2, dx = x - cx, dy = y - cy;
    const ok = key === 'ArrowRight' ? dx > 4 : key === 'ArrowLeft' ? dx < -4 : key === 'ArrowDown' ? dy > 4 : dy < -4;
    if (!ok) return;
    const along = key === 'ArrowRight' || key === 'ArrowLeft' ? Math.abs(dx) : Math.abs(dy), across = key === 'ArrowRight' || key === 'ArrowLeft' ? Math.abs(dy) : Math.abs(dx);
    const dist = along + across * 2.5;
    if (dist < bd) { bd = dist; best = c; }
  });
  return best;
}
root.addEventListener('keydown', e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key;
  if (k === 'Escape' && $('.abk-classes-app').hasAttribute('data-open') && root.clientWidth < 960) { act('closeside'); e.preventDefault(); return; }
  const card = e.target.closest && e.target.closest('.abk-classes-card');
  if (card && k.startsWith('Arrow')) {
    e.preventDefault();
    const nx = nearest(card, k);
    if (nx) { nx.focus(); if (root.clientWidth >= 960) select(nx.dataset.id); }
    return;
  }
  if (k === '[' || k === ']') { act('week', { dataset: { d: k === ']' ? 1 : -1 } }); e.preventDefault(); return; }
  if (k === 'o' || k === 'O') { act('open'); e.preventDefault(); return; }
  const c = C[S.sel];
  if (!c) return;
  if (k === 'b' || k === 'B') { e.preventDefault(); const st = state(c); if (!st) act(left(c) > 0 ? 'book' : 'wait'); else toast(st === 'booked' ? 'You’re already booked' : st === 'wait' ? 'You’re already on the waitlist' : 'This class has finished'); return; }
  if (k === 'c' || k === 'C') {
    e.preventDefault();
    const st = state(c);
    if (st === 'booked') act('cancel', { dataset: S.lateArm === c.id ? { confirm: '1' } : {} });
    else if (st === 'wait') act('leave');
    else toast('Nothing to cancel on this class');
  }
});

/* type filter chips */
$('[data-types]').innerHTML = Object.entries(TYPES).map(([k, t]) => '<button type="button" data-type="' + k + '" aria-pressed="false" style="--h:' + t.h + '"><i></i>' + t.name + '</button>').join('');
renderWeek();
renderWallet();
renderSide();

css:
.abk-tickets {
