  --abk-tickets-line2: color-mix(in oklch, var(--abk-tickets-ink) 20%, transparent);
  --abk-tickets-mute: color-mix(in oklch, var(--abk-tickets-ink) 58%, var(--abk-tickets-bg));
  --abk-tickets-z1: oklch(0.82 0.13 82);
  --abk-tickets-z2: oklch(0.72 0.15 30);
  --abk-tickets-z3: oklch(0.75 0.11 172);
  --abk-tickets-z4: oklch(0.72 0.1 252);
  --abk-tickets-z5: oklch(0.76 0.09 318);
  --abk-tickets-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-tickets-spring: linear(0, .1 6%, .38 13%, .74 21%, .97 29%, 1.07 36%, 1.08 43%, 1.04 53%, 1.005 66%, .997 80%, 1);
  --abk-tickets-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --abk-tickets-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-tickets-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-tickets;
  overflow: clip; isolation: isolate; border-radius: 16px;
  background: radial-gradient(120% 70% at 50% 0%, color-mix(in oklch, var(--abk-tickets-bg), var(--abk-tickets-z2) 10%), var(--abk-tickets-bg) 60%);
  color: var(--abk-tickets-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--abk-tickets-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & select, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; opacity: .35; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-tickets-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--abk-tickets-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid currentColor; opacity: .6; }

  & .abk-tickets-app { height: 100%; display: grid; grid-template: "top top top" auto "side map cart" minmax(0, 1fr) / 236px minmax(0, 1fr) 300px; }

  & .abk-tickets-top { grid-area: top; display: flex; align-items: center; gap: 22px; padding: 14px 20px; border-bottom: 1px solid var(--abk-tickets-line); }
  & .abk-tickets-venue { display: grid; line-height: 1.1; padding-right: 22px; border-right: 1px solid var(--abk-tickets-line2); flex: none;
    & b { font: italic 600 19px/1 var(--abk-tickets-serif); color: var(--abk-tickets-accent); }
    & span { font-size: 10px; font-weight: 700; letter-spacing: .18em; text-transform: uppercase; color: var(--abk-tickets-mute); margin-top: 4px; }
  }
  & .abk-tickets-event { min-width: 0;
    & h2 { font: 500 clamp(18px, 2.1cqi, 24px)/1.1 var(--abk-tickets-serif); letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & p { font-size: 12.5px; color: var(--abk-tickets-mute); margin-top: 3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .abk-tickets-date { margin-left: auto; display: grid; text-align: right; line-height: 1.2; flex: none;
    & b { font-size: 14px; } & span { font-size: 12px; color: var(--abk-tickets-mute); font-variant-numeric: tabular-nums; }
  }
  & .abk-tickets-hold { display: flex; align-items: center; gap: 8px; padding: 5px 12px 5px 6px; border-radius: 99px; background: var(--abk-tickets-raise); flex: none;
    transition: opacity .3s, translate .5s var(--abk-tickets-spring); @starting-style { opacity: 0; translate: 0 -6px; }
    & svg { width: 32px; height: 32px; rotate: -90deg; }
    & circle { stroke-width: 3; }
    & .abk-tickets-holdtrack { stroke: var(--abk-tickets-line2); }
    & .abk-tickets-holdbar { stroke: var(--abk-tickets-accent); stroke-dasharray: 94.25; stroke-dashoffset: calc(94.25 * (1 - var(--p, 1))); transition: stroke-dashoffset 1s linear, stroke .3s; }
    & div { display: grid; line-height: 1.1; }
    & b { font: 650 15px/1 var(--abk-tickets-mono); font-variant-numeric: tabular-nums; }
    & span { font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--abk-tickets-mute); }
    &[data-low] .abk-tickets-holdbar { stroke: var(--abk-tickets-z2); }
    &[data-low] b { color: var(--abk-tickets-z2); }
  }

  /* left: zones + best available */
  & .abk-tickets-side { grid-area: side; min-height: 0; overflow-y: auto; padding: 16px 14px; display: flex; flex-direction: column; gap: 10px; border-right: 1px solid var(--abk-tickets-line); scrollbar-width: thin;
    & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .16em; text-transform: uppercase; color: var(--abk-tickets-mute); padding: 0 4px; }
  }
  & .abk-tickets-zones { list-style: none; margin: 0 0 8px; padding: 0; display: grid; gap: 3px; }
  & .abk-tickets-zone { width: 100%; display: grid; grid-template-columns: 12px 1fr auto; gap: 1px 10px; align-items: center; text-align: left; padding: 8px 10px; border-radius: 10px; border: 1px solid transparent; transition: background .2s, border-color .2s, opacity .2s;
    & i { grid-row: span 2; width: 12px; height: 12px; border-radius: 50%; background: var(--z); box-shadow: 0 0 0 3px color-mix(in oklch, var(--z) 22%, transparent); }
    & b { font-size: 13.5px; font-weight: 600; }
    & output { font-weight: 650; font-variant-numeric: tabular-nums; }
    & small { grid-column: 2 / -1; font-size: 11.5px; color: var(--abk-tickets-mute); font-variant-numeric: tabular-nums; }
    & .abk-tickets-avail { grid-column: 2 / -1; height: 3px; border-radius: 3px; background: var(--abk-tickets-line); overflow: hidden; margin-top: 4px; }
    & .abk-tickets-avail span { display: block; height: 100%; width: calc(var(--f) * 100%); background: var(--z); border-radius: inherit; transition: width .6s var(--abk-tickets-ease); }
    &:hover { background: var(--abk-tickets-panel); }
    &[aria-pressed="true"] { background: var(--abk-tickets-raise); border-color: color-mix(in oklch, var(--z) 55%, transparent); }
  }
  & .abk-tickets-zones:has([aria-pressed="true"]) .abk-tickets-zone:not([aria-pressed="true"]) { opacity: .55; }
  & .abk-tickets-best { margin-top: auto; display: grid; gap: 10px; padding: 14px 12px; border-radius: 14px; background: var(--abk-tickets-panel); border: 1px solid var(--abk-tickets-line);
    & h3 { padding: 0; }
  }
  & .abk-tickets-qty { display: flex; align-items: center; gap: 6px;
    & button { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; background: var(--abk-tickets-raise); & svg { width: 15px; height: 15px; } }
    & button:hover:not(:disabled) { background: color-mix(in oklch, var(--abk-tickets-raise), var(--abk-tickets-ink) 10%); }
    & output { min-width: 26px; text-align: center; font: 600 20px/1 var(--abk-tickets-serif); font-variant-numeric: tabular-nums; }
    & span { font-size: 12px; color: var(--abk-tickets-mute); margin-left: 4px; }
  }
  & .abk-tickets-hint { font-size: 12px; color: var(--abk-tickets-mute); }
  & .abk-tickets-btn { height: 40px; border-radius: 11px; display: flex; align-items: center; justify-content: center; gap: 8px; font-weight: 650; font-size: 13.5px; background: var(--abk-tickets-ink); color: var(--abk-tickets-bg); transition: transform .3s var(--abk-tickets-spring), background .2s;
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: var(--abk-tickets-accent); }
    &:active:not(:disabled) { transform: scale(.97); }
    &[data-tone="ghost"] { background: none; color: var(--abk-tickets-ink); box-shadow: inset 0 0 0 1px var(--abk-tickets-line2); }
    &[data-tone="ghost"]:hover { background: var(--abk-tickets-panel); }
  }

  /* map */
  & .abk-tickets-map { grid-area: map; position: relative; min-height: 0; min-width: 0; overflow: hidden; }
  & .abk-tickets-chips { display: none; }
  & .abk-tickets-svg { width: 100%; height: 100%; touch-action: none; outline: none; cursor: grab;
    &:focus-visible { outline: 2px solid var(--abk-tickets-accent); outline-offset: -6px; border-radius: 12px; }
    &[data-panning] { cursor: grabbing; }
    & .abk-tickets-stage { fill: color-mix(in oklch, var(--abk-tickets-ink) 9%, transparent); stroke: var(--abk-tickets-line2); stroke-width: 1.5; }
    & .abk-tickets-stagelbl { fill: var(--abk-tickets-mute); stroke: none; font: 700 15px system-ui, sans-serif; letter-spacing: .4em; text-anchor: middle; }
    & .abk-tickets-rowlbl { fill: var(--abk-tickets-mute); stroke: none; font: 600 11px var(--abk-tickets-mono); text-anchor: middle; dominant-baseline: central; }
    & .abk-tickets-sect { fill: none; stroke: var(--abk-tickets-line2); stroke-width: 1.2; stroke-dasharray: 3 6; }
    & .abk-tickets-sectlbl { fill: var(--abk-tickets-mute); stroke: none; font: 700 12px system-ui, sans-serif; letter-spacing: .3em; text-anchor: middle; }
  }
  & .abk-tickets-seat { fill: var(--z); stroke: none; cursor: pointer; transform-box: fill-box; transform-origin: center;
    transition: fill .25s, opacity .3s, scale .45s var(--abk-tickets-spring), stroke-width .2s;
    &:hover { scale: 1.35; }
    &[data-sold] { fill: color-mix(in oklch, var(--abk-tickets-ink) 14%, transparent); cursor: default; &:hover { scale: 1; } }
    &[data-sel] { fill: var(--abk-tickets-ink); stroke: var(--z); stroke-width: 4; scale: 1.15; }
    &[data-dim] { opacity: .18; }
    &[data-pop] { animation: abk-tickets-pop .6s var(--abk-tickets-spring) both; animation-delay: calc(var(--i, 0) * 60ms); }
  }
  & .abk-tickets-cursor { fill: none; stroke: var(--abk-tickets-accent); stroke-width: 2.5; pointer-events: none; transition: cx .18s var(--abk-tickets-ease), cy .18s var(--abk-tickets-ease), opacity .2s; }
  & .abk-tickets-svg:not(:focus-visible) .abk-tickets-cursor { opacity: 0; }
  & .abk-tickets-tip { position: absolute; z-index: 5; left: 0; top: 0; pointer-events: none; padding: 8px 11px; border-radius: 10px; background: var(--abk-tickets-ink); color: var(--abk-tickets-bg); font-size: 12px; line-height: 1.3; white-space: nowrap; box-shadow: 0 10px 30px -10px rgb(0 0 0 / .6);
    translate: -50% calc(-100% - 10px); opacity: 0; scale: .96; transition: opacity .15s, scale .2s var(--abk-tickets-ease);
    &[data-on] { opacity: 1; scale: 1; }
    & b { display: block; font-size: 13px; }
    & span { color: color-mix(in oklch, var(--abk-tickets-bg) 65%, var(--abk-tickets-ink)); font-variant-numeric: tabular-nums; }
  }
  & .abk-tickets-zoom { position: absolute; right: 12px; top: 12px; display: grid; border-radius: 11px; overflow: hidden; background: var(--abk-tickets-panel); border: 1px solid var(--abk-tickets-line2);
    & button { width: 34px; height: 34px; display: grid; place-items: center; & svg { width: 16px; height: 16px; } }
    & button + button { border-top: 1px solid var(--abk-tickets-line); }
    & button:hover:not(:disabled) { background: var(--abk-tickets-raise); }
  }
  & .abk-tickets-legend { position: absolute; left: 14px; bottom: 12px; display: flex; gap: 14px; font-size: 11.5px; color: var(--abk-tickets-mute); pointer-events: none;
    & span { display: flex; align-items: center; gap: 6px; }
    & i { width: 10px; height: 10px; border-radius: 50%; background: var(--abk-tickets-z2); }
    & i[data-k="sel"] { background: var(--abk-tickets-ink); box-shadow: 0 0 0 2px var(--abk-tickets-z2); }
    & i[data-k="sold"] { background: color-mix(in oklch, var(--abk-tickets-ink) 16%, transparent); }
  }
  & .abk-tickets-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }

  /* cart */
  & .abk-tickets-cart { grid-area: cart; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--abk-tickets-line); background: var(--abk-tickets-panel); }
  & .abk-tickets-chead { display: flex; align-items: baseline; justify-content: space-between; padding: 16px 16px 8px;
    & h3 { font: 500 20px var(--abk-tickets-serif); }
    & button { font-size: 12px; font-weight: 650; color: var(--abk-tickets-mute); padding: 4px 6px; border-radius: 6px; }
    & button:hover { color: var(--abk-tickets-ink); background: var(--abk-tickets-raise); }
  }
  & .abk-tickets-closecart { display: none !important; }
  & .abk-tickets-items { flex: 1; min-height: 0; overflow-y: auto; padding: 0 10px; scrollbar-width: thin; }
  & .abk-tickets-group { margin: 6px 0 10px;
    & h4 { margin: 0; padding: 4px 6px; display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; color: var(--abk-tickets-mute); }
    & h4 i { width: 8px; height: 8px; border-radius: 50%; background: var(--z); }
  }
  & .abk-tickets-item { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto 26px; gap: 2px 10px; align-items: center; padding: 7px 6px; border-radius: 10px;
    animation: abk-tickets-in .35s var(--abk-tickets-ease) both; animation-delay: calc(var(--i, 0) * 40ms);
    & .abk-tickets-sn { grid-row: span 2; height: 38px; border-radius: 9px; display: grid; place-items: center; line-height: 1; background: var(--abk-tickets-raise); box-shadow: inset 3px 0 0 var(--z); }
    & .abk-tickets-sn small { font-size: 9px; color: var(--abk-tickets-mute); letter-spacing: .08em; }
    & .abk-tickets-sn b { font: 600 15px var(--abk-tickets-mono); }
    & span { font-size: 12.5px; font-weight: 600; }
    & select { grid-column: 2; justify-self: start; font-size: 11.5px; color: var(--abk-tickets-mute); background: none; border: 0; padding: 0; cursor: pointer; }
    & output { grid-row: span 2; font-weight: 650; font-variant-numeric: tabular-nums; font-size: 13.5px; }
    & button { grid-row: span 2; width: 26px; height: 26px; border-radius: 8px; display: grid; place-items: center; color: var(--abk-tickets-mute); & svg { width: 14px; height: 14px; } }
    & button:hover { background: var(--abk-tickets-raise); color: var(--abk-tickets-ink); }
    &:hover { background: color-mix(in oklch, var(--abk-tickets-panel), var(--abk-tickets-ink) 3%); }
  }
  & .abk-tickets-empty { padding: 30px 14px; display: grid; justify-items: center; gap: 10px; text-align: center; color: var(--abk-tickets-mute); font-size: 13px;
    & svg { width: 46px; height: 46px; stroke-width: 1.2; opacity: .7; }
  }
  & .abk-tickets-sum { padding: 12px 16px 16px; border-top: 1px dashed var(--abk-tickets-line2); display: grid; gap: 6px; font-variant-numeric: tabular-nums;
    & div { display: flex; justify-content: space-between; font-size: 12.5px; color: var(--abk-tickets-mute); }
    & div[data-total] { color: var(--abk-tickets-ink); font-size: 14px; font-weight: 650; align-items: baseline; margin: 4px 0 6px; }
    & div[data-total] output { font: 500 26px/1 var(--abk-tickets-serif); }
  }

  /* checkout sheet */
  & .abk-tickets-sheet { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 18px; background: color-mix(in oklch, var(--abk-tickets-bg) 70%, transparent); backdrop-filter: blur(8px);
    visibility: hidden; opacity: 0; transition: opacity .25s, visibility 0s .25s;
    &[data-open] { visibility: visible; opacity: 1; transition: opacity .3s; }
  }
  & .abk-tickets-dialog { width: min(560px, 100%); max-height: 100%; overflow-y: auto; border-radius: 20px; background: var(--abk-tickets-panel); border: 1px solid var(--abk-tickets-line2); padding: 22px; display: grid; gap: 14px; box-shadow: 0 40px 90px -30px rgb(0 0 0 / .7);
    translate: 0 16px; scale: .97; transition: translate .6s var(--abk-tickets-spring), scale .6s var(--abk-tickets-spring);
    & h3 { font: 500 24px/1.1 var(--abk-tickets-serif); }
    & label { display: grid; gap: 5px; font-size: 12px; font-weight: 650; color: var(--abk-tickets-mute); }
    & input { height: 40px; border-radius: 10px; border: 1px solid var(--abk-tickets-line2); background: var(--abk-tickets-bg); padding: 0 12px; font-size: 14px; outline: none; }
    & input:focus { border-color: var(--abk-tickets-accent); }
    & input[aria-invalid="true"] { border-color: var(--abk-tickets-z2); }
    & em { font-style: normal; font-size: 11.5px; color: var(--abk-tickets-z2); }
    & .abk-tickets-row2 { display: grid; grid-template-columns: 1fr 1.4fr; gap: 8px; }
  }
  & .abk-tickets-sheet[data-open] .abk-tickets-dialog { translate: 0; scale: 1; }
  & .abk-tickets-lines { display: grid; gap: 4px; font-size: 13px; font-variant-numeric: tabular-nums;
    & div { display: flex; justify-content: space-between; gap: 12px; }
    & div span:first-child { color: var(--abk-tickets-mute); }
    & div[data-total] { border-top: 1px solid var(--abk-tickets-line2); padding-top: 8px; margin-top: 4px; font-weight: 650; font-size: 15px; }
    & div[data-total] span:first-child { color: var(--abk-tickets-ink); }
  }
  & .abk-tickets-progress { height: 3px; border-radius: 3px; background: var(--abk-tickets-line); overflow: hidden; & i { display: block; height: 100%; width: 0; background: var(--abk-tickets-accent); } }
  & .abk-tickets-progress[data-run] i { animation: abk-tickets-load 1.3s var(--abk-tickets-ease) forwards; }
  & .abk-tickets-stubs { display: grid; gap: 10px; }
  & .abk-tickets-stub { --abk-tickets-notch: radial-gradient(circle at 0 50%, transparent 9px, #000 9.5px) left / 51% 100% no-repeat, radial-gradient(circle at 100% 50%, transparent 9px, #000 9.5px) right / 51% 100% no-repeat;
    display: grid; grid-template-columns: 1fr auto; gap: 2px 16px; padding: 14px 22px; color: var(--abk-tickets-bg); background: linear-gradient(90deg, var(--z), color-mix(in oklch, var(--z), white 30%));
    -webkit-mask: var(--abk-tickets-notch); mask: var(--abk-tickets-notch); border-radius: 10px;
    animation: abk-tickets-deal .7s var(--abk-tickets-spring) both; animation-delay: calc(var(--i, 0) * 90ms);
    & small { font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; opacity: .7; }
    & b { font: 600 17px var(--abk-tickets-serif); }
    & .abk-tickets-code { grid-row: span 2; align-self: center; width: 84px; height: 34px; background: repeating-linear-gradient(90deg, currentColor 0 var(--a, 2px), transparent 0 calc(var(--a, 2px) + var(--b, 3px))); opacity: .8; }
  }
  & .abk-tickets-acts { display: grid; grid-template-columns: 1fr 1.6fr; gap: 8px; }

  & .abk-tickets-toast { position: absolute; z-index: 40; left: 50%; bottom: 16px; display: flex; align-items: center; gap: 14px; padding: 9px 9px 9px 16px; border-radius: 12px; background: var(--abk-tickets-ink); color: var(--abk-tickets-bg); font-size: 13px; font-weight: 550; box-shadow: 0 14px 40px -12px rgb(0 0 0 / .6); max-width: calc(100% - 24px);
    translate: -50% 16px; opacity: 0; visibility: hidden; transition: translate .3s var(--abk-tickets-ease), opacity .2s, visibility 0s .3s;
    &[data-open] { translate: -50% 0; opacity: 1; visibility: visible; transition: translate .5s var(--abk-tickets-spring), opacity .2s; }
    & button { font-weight: 750; font-size: 12.5px; padding: 6px 10px; border-radius: 8px; color: oklch(0.5 0.15 30); }
    & button:hover { background: color-mix(in oklch, var(--abk-tickets-bg) 10%, transparent); }
  }
  & .abk-tickets-bar { display: none; }

  @container abk-tickets (max-width: 1040px) {
    & .abk-tickets-event p { display: none; }
  }
  @container abk-tickets (max-width: 959px) {
    & .abk-tickets-app { grid-template: "top top" auto "map cart" minmax(0, 1fr) / minmax(0, 1fr) 280px; }
    & .abk-tickets-side { display: none; }
    & .abk-tickets-venue { display: none; }
    & .abk-tickets-chips { position: absolute; z-index: 4; left: 10px; right: 56px; top: 10px; display: flex; gap: 5px; overflow-x: auto; scrollbar-width: none;
      & button { flex: none; height: 30px; padding: 0 10px; border-radius: 99px; display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 650; background: var(--abk-tickets-panel); border: 1px solid var(--abk-tickets-line2); font-variant-numeric: tabular-nums; }
      & button i { width: 8px; height: 8px; border-radius: 50%; background: var(--z); }
      & button[aria-pressed="true"] { background: var(--abk-tickets-ink); color: var(--abk-tickets-bg); }
    }
    & .abk-tickets-chips [data-act="best"] { background: var(--abk-tickets-accent); color: var(--abk-tickets-bg); border-color: transparent; }
  }
  @container abk-tickets (max-width: 759px) {
    & .abk-tickets-app { grid-template: "top" auto "map" minmax(0, 1fr) "bar" auto / minmax(0, 1fr); }
    & .abk-tickets-top { gap: 10px; padding: 10px 12px; flex-wrap: wrap; }
    & .abk-tickets-event h2 { font-size: 17px; }
    & .abk-tickets-date { display: none; }
    & .abk-tickets-hold { margin-left: auto; }
    & .abk-tickets-legend { display: none; }
    & .abk-tickets-cart { position: absolute; z-index: 20; left: 0; right: 0; bottom: 0; height: min(72%, 470px); border: 1px solid var(--abk-tickets-line2); border-radius: 18px 18px 0 0; box-shadow: 0 -30px 60px -30px rgb(0 0 0 / .7);
      translate: 0 104%; visibility: hidden; transition: translate .35s var(--abk-tickets-ease), visibility 0s .35s; }
    & .abk-tickets-closecart { display: grid !important; width: 30px; height: 30px; place-items: center; & svg { width: 16px; height: 16px; } }
    & .abk-tickets-chead h3 { margin-right: auto; }
    & .abk-tickets-app[data-cart-open] .abk-tickets-cart { translate: 0; visibility: visible; transition: translate .5s var(--abk-tickets-spring); }
    & .abk-tickets-bar { grid-area: bar; display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-top: 1px solid var(--abk-tickets-line); background: var(--abk-tickets-panel);
      & div { flex: 1; display: grid; line-height: 1.2; }
