      '<p style="font-size:13px;color:var(--abk-tickets-mute)">' + items.length + ' e-ticket' + (items.length === 1 ? '' : 's') + ' sent to ' + email.value.trim() + ' · order CH-' + (73000 + items[0].s.i * 7) + ' · ' + eur(T.total) + ' paid</p>' +
      '<div class="abk-tickets-stubs">' + items.map((x, j) => '<div class="abk-tickets-stub" style="--z:var(--abk-tickets-' + x.s.zone + ');--i:' + j + '"><small>' + ZONES[x.s.zone].name + ' · Sat 14 Nov 19:30</small><span class="abk-tickets-code" style="--a:' + (1 + (x.s.i % 3)) + 'px;--b:' + (2 + (x.s.i % 4)) + 'px"></span><b>Row ' + x.s.label + ' · Seat ' + x.s.n + '</b></div>').join('') + '</div>' +
      '<div class="abk-tickets-acts"><button type="button" class="abk-tickets-btn" data-tone="ghost" data-act="wallet">Add to wallet</button><button type="button" class="abk-tickets-btn" data-act="closesheet">Done</button></div></div>';
  }, RM.matches ? 200 : 1350);
}

/* ── tooltip + cursor ── */
function showTip(s) {
  const tip = $('[data-tip]');
  if (!s) { tip.removeAttribute('data-on'); return; }
  const el = seatEl(s.i), r = el.getBoundingClientRect(), m = $('.abk-tickets-map').getBoundingClientRect();
  tip.innerHTML = '<b>Row ' + s.label + ' · Seat ' + s.n + '</b><span>' + ZONES[s.zone].name + ' · ' + (s.sold ? 'Sold' : '€' + ZONES[s.zone].price) + '</span>';
  tip.style.left = Math.max(70, Math.min(m.width - 70, r.left - m.left + r.width / 2)) + 'px';
  tip.style.top = (r.top - m.top) + 'px';
  tip.setAttribute('data-on', '');
}
function placeCursor() {
  const c = $('[data-cursor]'), s = SEATS[S.cursor];
  if (!s) return;
  c.setAttribute('cx', s.x.toFixed(1)); c.setAttribute('cy', s.y.toFixed(1));
  $('[data-live]').textContent = label(s);
  const v = S.vb;
  if (s.x < v.x + 20 || s.x > v.x + v.w - 20 || s.y < v.y + 20 || s.y > v.y + v.h - 20) zoomTo({ x: s.x - v.w / 2, y: s.y - v.h / 2, w: v.w, h: v.h });
}
function moveCursor(key) {
  const s = SEATS[S.cursor == null ? 0 : S.cursor], row = ROWS[s.row];
  if (S.cursor == null) { S.cursor = SEATS.find(x => !x.sold).i; placeCursor(); return; }
  let next = null;
  if (key === 'ArrowLeft' || key === 'ArrowRight') {
    const j = row.seats.indexOf(s) + (key === 'ArrowRight' ? 1 : -1);
    next = row.seats[j];
  } else {
    const r2 = ROWS[s.row + (key === 'ArrowDown' ? 1 : -1)];
    if (r2) next = r2.seats.reduce((b, x) => Math.abs(x.th - s.th) < Math.abs(b.th - s.th) ? x : b, r2.seats[0]);
  }
  if (next) { S.cursor = next.i; placeCursor(); }
}

/* ── toast ── */
function toast(msg, undo) {
  const t = $('.abk-tickets-toast');
  $('[data-msg]', t).textContent = msg;
  undoFn = undo || null;
  $('[data-act="undo"]', t).hidden = !undo;
  t.setAttribute('data-open', '');
  clearTimeout(toastT);
  toastT = setTimeout(() => t.removeAttribute('data-open'), 4200);
}

/* ── events ── */
let pan = null, moved = false;
const svgEl = $('[data-svg]');
svgEl.addEventListener('pointerdown', e => {
  if (e.button !== 0) return;
  pan = { x: e.clientX, y: e.clientY, vb: { ...S.vb } }; moved = false;
  try { svgEl.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointers cannot be captured */ }
});
svgEl.addEventListener('pointermove', e => {
  if (!pan) {
    const s = e.target.closest && e.target.closest('.abk-tickets-seat');
    showTip(s ? SEATS[+s.dataset.i] : null);
    return;
  }
  const dx = e.clientX - pan.x, dy = e.clientY - pan.y;
  if (!moved && Math.hypot(dx, dy) < 5) return;
  if (S.vb.w >= FIT.w - .5) return;
  moved = true; svgEl.setAttribute('data-panning', ''); showTip(null);
  const r = svgEl.getBoundingClientRect(), k = Math.max(pan.vb.w / r.width, pan.vb.h / r.height);
  cancelAnimationFrame(tween);
  setVB(clampVB({ x: pan.vb.x - dx * k, y: pan.vb.y - dy * k, w: pan.vb.w, h: pan.vb.h }));
});
const endPan = () => { pan = null; svgEl.removeAttribute('data-panning'); };
svgEl.addEventListener('pointerup', endPan);
svgEl.addEventListener('pointercancel', endPan);
svgEl.addEventListener('pointerleave', () => { if (!pan) showTip(null); });
svgEl.addEventListener('click', e => {
  if (moved) { moved = false; return; }
  const s = e.target.closest('.abk-tickets-seat');
  if (!s) return;
  S.cursor = +s.dataset.i; placeCursor();
  toggle(+s.dataset.i);
});
svgEl.addEventListener('wheel', e => {
  if (!e.ctrlKey && !e.metaKey) return;
  e.preventDefault();
  const r = svgEl.getBoundingClientRect(), k = Math.max(S.vb.w / r.width, S.vb.h / r.height);
  const ox = (r.width - S.vb.w / k) / 2, oy = (r.height - S.vb.h / k) / 2;
  const cx = S.vb.x + (e.clientX - r.left - ox) * k, cy = S.vb.y + (e.clientY - r.top - oy) * k;
  const v = S.vb, w = Math.max(240, Math.min(FIT.w, v.w * Math.exp(e.deltaY * .01))), f = w / v.w;
  cancelAnimationFrame(tween);
  setVB(w >= FIT.w ? { ...FIT } : clampVB({ x: cx - (cx - v.x) * f, y: cy - (cy - v.y) * f, w, h: w * FIT.h / FIT.w }));
}, { passive: false });
svgEl.addEventListener('focus', () => { if (S.cursor == null) { S.cursor = (SEATS.find(x => x.zone === 'z1' && !x.sold) || SEATS[0]).i; } placeCursor(); });

root.addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b || !root.contains(b)) return;
  if (b.dataset.zone) {
    const z = b.dataset.zone;
    S.zone = S.zone === z ? null : z;
    paintAll(); renderZones();
    if (S.zone) fitSeats(SEATS.filter(s => s.zone === z), 40); else zoomTo(FIT);
    return;
  }
  if (b.dataset.remove) { const i = +b.dataset.remove, t = S.sel.get(i); S.sel.delete(i); paintSeat(SEATS[i]); afterSelect(); toast('Removed row ' + SEATS[i].label + ' seat ' + SEATS[i].n, () => { S.sel.set(i, t); paintSeat(SEATS[i]); afterSelect(); }); return; }
  switch (b.dataset.act) {
    case 'qty': S.qty = Math.max(1, Math.min(MAXSEATS, S.qty + +b.dataset.d)); renderZones(); break;
    case 'best': bestAvailable(); break;
    case 'zoom': zoomBy(+b.dataset.d > 0 ? 1.6 : 1 / 1.6); break;
    case 'fit': zoomTo(FIT); break;
    case 'clear': { const prev = new Map(S.sel); S.sel.clear(); paintAll(); afterSelect(); toast('Released ' + prev.size + ' seat' + (prev.size === 1 ? '' : 's'), () => { S.sel = prev; paintAll(); afterSelect(); }); break; }
    case 'checkout': openSheet(); break;
    case 'closesheet': closeSheet(); break;
    case 'wallet': toast('Tickets added to your wallet'); break;
    case 'togglecart': S.cartOpen = !S.cartOpen; $('.abk-tickets-app').toggleAttribute('data-cart-open', S.cartOpen); renderCart(); break;
    case 'closecart': S.cartOpen = false; $('.abk-tickets-app').removeAttribute('data-cart-open'); renderCart(); break;
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); } $('.abk-tickets-toast').removeAttribute('data-open'); break;
  }
});
root.addEventListener('change', e => {
  if (e.target.dataset.type) { S.sel.set(+e.target.dataset.type, e.target.value); renderCart(); const s = $('[data-type="' + e.target.dataset.type + '"]'); if (s) s.focus(); }
});
root.addEventListener('submit', e => { e.preventDefault(); pay(e.target); });
root.addEventListener('keydown', e => {
  if (e.key === 'Escape' && $('[data-sheet]').hasAttribute('data-open')) { if (!S.busy) closeSheet(); e.preventDefault(); return; }
  if (e.target.matches('input, select, textarea')) return;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const onMap = e.target === svgEl;
  if (onMap && e.key.startsWith('Arrow')) { e.preventDefault(); moveCursor(e.key); return; }
  if (onMap && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); if (S.cursor != null) { toggle(S.cursor); $('[data-live]').textContent = label(SEATS[S.cursor]); } return; }
  if (e.key === '+' || e.key === '=') { zoomBy(1.6); e.preventDefault(); }
  else if (e.key === '-') { zoomBy(1 / 1.6); e.preventDefault(); }
  else if (e.key === '0') { zoomTo(FIT); e.preventDefault(); }
  else if (e.key === 'b' || e.key === 'B') { bestAvailable(); e.preventDefault(); }
});

drawHall();
/* a party of two already picked in prime stalls, so the basket and hold timer have something to show */
(() => { const all = runs('z1', 2).sort((a, b) => score(a) - score(b)), c = all[Math.min(2, all.length - 1)]; if (c) { c.forEach(s => S.sel.set(s.i, 'std')); S.sel.set(c[1].i, 'con'); } paintAll(); afterSelect(); })();

css:
.abk-desks {
  --abk-desks-bg: oklch(0.974 0.007 95);
  --abk-desks-ink: oklch(0.26 0.03 255);
  --abk-desks-accent: oklch(0.55 0.13 158);
  --abk-desks-heat: oklch(0.74 0.16 58);
  --abk-desks-paper: oklch(0.995 0.003 95);
  --abk-desks-line: color-mix(in oklch, var(--abk-desks-ink) 10%, transparent);
  --abk-desks-line2: color-mix(in oklch, var(--abk-desks-ink) 19%, transparent);
  --abk-desks-mute: color-mix(in oklch, var(--abk-desks-ink) 56%, var(--abk-desks-bg));
  --abk-desks-soft: color-mix(in oklch, var(--abk-desks-ink) 4%, var(--abk-desks-bg));
  --abk-desks-tint: color-mix(in oklch, var(--abk-desks-accent) 12%, var(--abk-desks-paper));
  --abk-desks-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-desks-spring: linear(0, .1 6%, .38 13%, .74 21%, .97 29%, 1.07 36%, 1.08 43%, 1.04 53%, 1.005 66%, .997 80%, 1);
  --abk-desks-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-desks-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-desks;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--abk-desks-line2);
  background: var(--abk-desks-bg); color: var(--abk-desks-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--abk-desks-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-desks-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--abk-desks-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--abk-desks-line2); border-bottom-width: 2px; color: var(--abk-desks-mute); background: var(--abk-desks-paper); }

  & .abk-desks-app { height: 100%; display: grid; grid-template: "top top top" auto "left plan right" minmax(0, 1fr) / 252px minmax(0, 1fr) 292px; }

  & .abk-desks-top { grid-area: top; display: flex; align-items: center; gap: 16px; padding: 11px 16px; border-bottom: 1px solid var(--abk-desks-line2); background: var(--abk-desks-paper); }
  & .abk-desks-brand { display: flex; align-items: center; gap: 10px;
    & svg { width: 32px; height: 32px; padding: 6px; border-radius: 9px; background: var(--abk-desks-ink); color: var(--abk-desks-paper); }
    & div { display: grid; line-height: 1.15; }
    & b { font-size: 15px; font-weight: 750; letter-spacing: -.01em; }
    & span { font-size: 11.5px; color: var(--abk-desks-mute); }
  }
  & .abk-desks-occ { margin-left: auto; display: flex; align-items: center; gap: 12px; font-size: 12px; color: var(--abk-desks-mute); font-variant-numeric: tabular-nums;
    & b { color: var(--abk-desks-ink); font-size: 13px; }
    & .abk-desks-bar { width: 120px; height: 6px; border-radius: 6px; background: var(--abk-desks-line); overflow: hidden; display: flex; }
    & .abk-desks-bar i { height: 100%; width: calc(var(--f) * 100%); background: var(--abk-desks-ink); transition: width .6s var(--abk-desks-ease); }
    & .abk-desks-bar i + i { background: var(--abk-desks-heat); }
  }
  & .abk-desks-views { display: none; }

  & .abk-desks-left { grid-area: left; min-height: 0; overflow-y: auto; padding: 14px; display: flex; flex-direction: column; gap: 18px; border-right: 1px solid var(--abk-desks-line2); scrollbar-width: thin;
    & section { display: grid; gap: 8px; }
    & h3 { font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--abk-desks-mute); display: flex; justify-content: space-between; }
  }
  & .abk-desks-days { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 4px; }
  & .abk-desks-day { display: grid; justify-items: center; gap: 1px; padding: 6px 0 7px; border-radius: 9px; border: 1px solid var(--abk-desks-line); background: var(--abk-desks-paper); line-height: 1.1; transition: background .2s, color .2s, border-color .2s;
    & small { font-size: 9.5px; font-weight: 750; letter-spacing: .08em; text-transform: uppercase; color: var(--abk-desks-mute); }
    & b { font-size: 15px; font-weight: 700; font-variant-numeric: tabular-nums; }
    & i { width: 70%; height: 3px; border-radius: 3px; margin-top: 3px; background: linear-gradient(90deg, var(--abk-desks-ink) calc(var(--f) * 100%), var(--abk-desks-line) 0); }
    &:hover { border-color: var(--abk-desks-ink); }
    &[aria-checked="true"] { background: var(--abk-desks-ink); color: var(--abk-desks-paper); border-color: var(--abk-desks-ink); & small { color: inherit; opacity: .7; } & i { background: linear-gradient(90deg, var(--abk-desks-heat) calc(var(--f) * 100%), color-mix(in oklch, var(--abk-desks-paper) 25%, transparent) 0); } }
    &[data-mine]::after { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--abk-desks-accent); margin-top: 3px; }
  }
  & .abk-desks-half { display: grid; grid-template-columns: repeat(3, 1fr); padding: 3px; border-radius: 10px; background: var(--abk-desks-soft); border: 1px solid var(--abk-desks-line);
    & button { height: 28px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--abk-desks-mute); }
    & button[aria-checked="true"] { background: var(--abk-desks-paper); color: var(--abk-desks-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--abk-desks-ink) 18%, transparent); }
  }
  & .abk-desks-needs { display: flex; flex-wrap: wrap; gap: 5px;
    & button { height: 30px; padding: 0 10px 0 8px; border-radius: 99px; border: 1px solid var(--abk-desks-line2); display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; background: var(--abk-desks-paper); transition: background .2s, color .2s, border-color .2s; }
    & button svg { width: 15px; height: 15px; }
    & button:hover { border-color: var(--abk-desks-ink); }
    & button[aria-pressed="true"] { background: var(--abk-desks-tint); border-color: var(--abk-desks-accent); color: color-mix(in oklch, var(--abk-desks-accent) 70%, var(--abk-desks-ink)); }
  }
  & .abk-desks-team { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
  & .abk-desks-mate { width: 100%; display: grid; grid-template-columns: 32px minmax(0, 1fr) 20px; gap: 0 10px; align-items: center; text-align: left; padding: 6px 8px; border-radius: 10px; transition: background .2s;
    & .abk-desks-av { grid-row: span 2; width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 750; color: oklch(0.3 0.07 var(--h)); background: oklch(0.9 0.05 var(--h)); }
    & b { font-size: 13px; font-weight: 600; }
    & small { grid-column: 2; font-size: 11.5px; color: var(--abk-desks-mute); font-variant-numeric: tabular-nums; }
    & .abk-desks-box { grid-row: 1 / span 2; grid-column: 3; width: 18px; height: 18px; border-radius: 5px; border: 1.5px solid var(--abk-desks-line2); display: grid; place-items: center; transition: background .2s, border-color .2s; }
    & .abk-desks-box svg { width: 12px; height: 12px; stroke-width: 2.6; color: var(--abk-desks-paper); opacity: 0; scale: .5; transition: opacity .2s, scale .35s var(--abk-desks-spring); }
    &:hover { background: var(--abk-desks-soft); }
    &[aria-checked="true"] .abk-desks-box { background: var(--abk-desks-heat); border-color: var(--abk-desks-heat); & svg { opacity: 1; scale: 1; } }
    &[aria-disabled="true"] { opacity: .55; }
  }

  /* plan */
  & .abk-desks-plan { grid-area: plan; position: relative; min-height: 0; min-width: 0; overflow: hidden;
    background: linear-gradient(var(--abk-desks-line) 1px, transparent 1px) 0 0 / 24px 24px, linear-gradient(90deg, var(--abk-desks-line) 1px, transparent 1px) 0 0 / 24px 24px, var(--abk-desks-bg); }
  & .abk-desks-svg { width: 100%; height: 100%; padding: 10px 10px 36px;
    & .abk-desks-wall { fill: var(--abk-desks-paper); stroke: var(--abk-desks-ink); stroke-width: 5; stroke-linejoin: miter; }
    & .abk-desks-win { stroke: oklch(0.72 0.08 230); stroke-width: 3; }
    & .abk-desks-room { fill: color-mix(in oklch, var(--abk-desks-ink) 5%, var(--abk-desks-paper)); stroke: var(--abk-desks-ink); stroke-width: 2; }
    & .abk-desks-core { fill: url(#abk-desks-hatch); stroke: var(--abk-desks-ink); stroke-width: 2; }
    & .abk-desks-zone { fill: color-mix(in oklch, var(--abk-desks-accent) 5%, transparent); stroke: color-mix(in oklch, var(--abk-desks-accent) 40%, transparent); stroke-width: 1.5; stroke-dasharray: 5 5; }
    & .abk-desks-lbl { fill: var(--abk-desks-mute); stroke: none; font: 700 12px system-ui, sans-serif; letter-spacing: .14em; text-transform: uppercase; }
    & .abk-desks-lbl2 { fill: var(--abk-desks-ink); stroke: none; font: 650 14px system-ui, sans-serif; }
    & .abk-desks-heatc { stroke: none; mix-blend-mode: multiply; transition: r .9s var(--abk-desks-spring), opacity .5s; @starting-style { r: 0; opacity: 0; } }
    & .abk-desks-heatc[data-out] { r: 0; opacity: 0; }
    & .abk-desks-link { stroke: var(--abk-desks-heat); stroke-width: 2; stroke-dasharray: 2 6; fill: none; animation: abk-desks-march 1s linear infinite; }
    & .abk-desks-linklbl { fill: color-mix(in oklch, var(--abk-desks-heat) 55%, var(--abk-desks-ink)); stroke: none; font: 700 11px var(--abk-desks-mono); paint-order: stroke; }
    & .abk-desks-linkbg { fill: var(--abk-desks-paper); stroke: color-mix(in oklch, var(--abk-desks-heat) 50%, transparent); stroke-width: 1; }
  }
  & .abk-desks-desk { cursor: pointer; outline: none;
    & .abk-desks-top2 { fill: var(--abk-desks-paper); stroke: var(--abk-desks-accent); stroke-width: 2; transform-box: fill-box; transform-origin: center; transition: fill .25s, stroke .25s, opacity .3s; }
    & .abk-desks-chair { fill: var(--abk-desks-paper); stroke: var(--abk-desks-line2); stroke-width: 1.5; transition: fill .25s; }
    & text { fill: color-mix(in oklch, var(--abk-desks-accent) 70%, var(--abk-desks-ink)); stroke: none; font: 650 13px var(--abk-desks-mono); text-anchor: middle; dominant-baseline: central; pointer-events: none; }
    &:hover .abk-desks-top2 { fill: var(--abk-desks-tint); }
    &[data-s="taken"] { & .abk-desks-top2 { fill: url(#abk-desks-hatch); stroke: var(--abk-desks-line2); } & text { fill: var(--abk-desks-mute); } & .abk-desks-chair { fill: var(--abk-desks-line2); } }
    &[data-s="mate"] { & .abk-desks-top2 { fill: oklch(0.9 0.05 var(--h)); stroke: oklch(0.55 0.1 var(--h)); } & text { fill: oklch(0.3 0.08 var(--h)); font-family: system-ui, sans-serif; font-weight: 750; } & .abk-desks-chair { fill: oklch(0.55 0.1 var(--h)); } }
    &[data-s="mine"] { & .abk-desks-top2 { fill: var(--abk-desks-ink); stroke: var(--abk-desks-ink); } & text { fill: var(--abk-desks-paper); font-family: system-ui, sans-serif; font-weight: 750; } & .abk-desks-chair { fill: var(--abk-desks-ink); } }
    &[data-s="half"] .abk-desks-top2 { fill: url(#abk-desks-halfg); }
    &[data-dim] { opacity: .28; }
    &[aria-current="true"] .abk-desks-top2, &:focus-visible .abk-desks-top2 { stroke: var(--abk-desks-ink); stroke-width: 3.5; }
