/* Northlight Works desk booking. Choose teammates and the plan grows a heat field around their desks
   (SVG radial gradients whose r and opacity transition in from @starting-style). Every free desk that
   passes your filters is scored by a Gaussian of its distance to them; the best three are ranked. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const IC = {
  win: '<path d="M4 4h16v16H4zM12 4v16M4 12h16"/>', dual: '<rect x="2.5" y="5" width="8.5" height="7" rx="1"/><rect x="13" y="5" width="8.5" height="7" rx="1"/><path d="M6.5 12v3M17 12v3M4 18h16"/>',
  stand: '<path d="M4 9h16M7 9v11M17 9v11M9 5h6"/><path d="M12 5V3"/>', quiet: '<path d="M4 10v4h3l5 4V6L7 10H4Z"/><path d="m16 9 5 6M21 9l-5 6"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>', pin: '<path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0 1 13 0c0 5.4-6.5 11-6.5 11Z"/><circle cx="12" cy="10" r="2.3"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

const MON0 = new Date(2026, 9, 5), TODAY = 1;   /* week of Mon 5 Oct 2026, today is Tue 6 Oct */
const DN = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'], MN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const dateOf = i => new Date(MON0.getFullYear(), MON0.getMonth(), MON0.getDate() + Math.floor(i / 5) * 7 + i % 5);
const dayLabel = i => { const d = dateOf(i); return DN[i % 5] + ' ' + d.getDate() + ' ' + MN[d.getMonth()]; };
const NDAYS = 10, M_PER_UNIT = .026, SIGMA = 115;
const HALVES = { all: 'All day', am: 'Morning', pm: 'Afternoon' };
const NEEDS = { window: ['Window', 'win'], dual: ['Dual monitor', 'dual'], stand: ['Standing', 'stand'], quiet: ['Quiet zone', 'quiet'] };

/* ── floor geometry ── */
const PODS = [
  { id: 'A', x: 58, y: 66, cols: 3 }, { id: 'B', x: 264, y: 66, cols: 3 }, { id: 'C', x: 470, y: 66, cols: 3 },
  { id: 'D', x: 58, y: 246, cols: 3 }, { id: 'E', x: 264, y: 246, cols: 3 }, { id: 'H', x: 470, y: 246, cols: 2 },
  { id: 'F', x: 64, y: 448, cols: 2 }, { id: 'G', x: 222, y: 448, cols: 2 }
];
const DW = 62, DH = 36;
const DESKS = [];
PODS.forEach(p => {
  for (let r = 0; r < 2; r++) for (let c = 0; c < p.cols; c++) {
    const n = DESKS.length + 1, x = p.x + c * (DW + 3), y = p.y + r * (DH + 3);
    const d = { id: '3.' + String(n).padStart(2, '0'), i: DESKS.length, pod: p.id, r, c, x, y, cx: x + DW / 2, cy: y + DH / 2, am: [], pm: [] };
    d.window = (r === 0 && 'ABC'.includes(p.id)) || (p.id === 'D' && c === 0) || (p.id === 'F' && c === 0);
    d.dual = 'BCEH'.includes(p.id);
    d.stand = p.id === 'H' || n % 7 === 3;
    d.quiet = 'FG'.includes(p.id);
    DESKS.push(d);
  }
});
const byId = Object.fromEntries(DESKS.map(d => [d.id, d]));

/* ── people ── */
const TEAM = [
  { id: 'priya', name: 'Priya Raman', ini: 'PR', h: 25, role: 'Design lead', days: { 1: ['3.15', 'all'], 2: ['3.15', 'all'], 3: ['3.15', 'all'], 6: ['3.15', 'all'], 7: ['3.15', 'all'] } },
  { id: 'tomas', name: 'Tomás Ferreira', ini: 'TF', h: 205, role: 'Product designer', days: { 1: ['3.10', 'all'], 3: ['3.10', 'all'], 6: ['3.10', 'all'], 8: ['3.10', 'all'] } },
  { id: 'mei', name: 'Mei Lin', ini: 'ML', h: 320, role: 'Researcher', days: { 2: ['3.27', 'all'], 4: ['3.27', 'am'], 7: ['3.27', 'all'] } },
  { id: 'jonas', name: 'Jonas Aalto', ini: 'JA', h: 140, role: 'Content designer', days: { 1: ['3.32', 'pm'], 3: ['3.32', 'all'], 8: ['3.32', 'all'] } },
  { id: 'ruth', name: 'Ruth Okafor', ini: 'RO', h: 70, role: 'Design systems', days: { 0: ['3.05', 'all'], 1: ['3.05', 'am'], 5: ['3.05', 'all'] } },
  { id: 'sam', name: 'Sam Whitlock', ini: 'SW', h: 280, role: 'Illustrator', days: {} }
];
const MATE = Object.fromEntries(TEAM.map(t => [t.id, t]));
/* everyone else: seeded half-day bookings, busier mid-week */
const OCC = [.5, .64, .72, .66, .38];
const taken = {};   /* key day|deskId -> {am, pm} : 'x' (someone), mate id, or 'me' */
for (let day = 0; day < NDAYS; day++) {
  const r = rng(day * 7919 + 11);
  DESKS.forEach(d => {
    const p = OCC[day % 5] * (d.window ? 1.15 : 1) * (d.quiet ? .8 : 1);
    const am = r() < p, pm = am ? r() < .78 : r() < p * .35;
    taken[day + '|' + d.id] = { am: am ? 'x' : null, pm: pm ? 'x' : null };
  });
  TEAM.forEach(t => { const b = t.days[day]; if (b) { const k = taken[day + '|' + b[0]]; k.am = b[1] !== 'pm' ? t.id : null; k.pm = b[1] !== 'am' ? t.id : null; } });
}
const book = (day, id, half) => { const k = taken[day + '|' + id]; if (half !== 'pm') k.am = 'me'; if (half !== 'am') k.pm = 'me'; };
book(3, '3.09', 'all');

const S = { day: TODAY, half: 'all', needs: new Set(), near: new Set(['priya', 'tomas']), sel: null, view: 'plan' };
let undoFn = null, toastT = 0;

const slot = (day, id) => taken[day + '|' + id];
const halves = h => h === 'all' ? ['am', 'pm'] : [h];
const freeFor = (day, id, h) => halves(h).every(x => !slot(day, id)[x]);
const myDesk = day => DESKS.find(d => { const k = slot(day, d.id); return k.am === 'me' || k.pm === 'me'; });
const passes = d => [...S.needs].every(n => d[n]);
const present = (t, day) => t.days[day] && (S.half === 'all' || t.days[day][1] === 'all' || t.days[day][1] === S.half) ? byId[t.days[day][0]] : null;
const dist = (a, b) => Math.hypot(a.cx - b.cx, a.cy - b.cy);
const meters = u => (u * M_PER_UNIT).toFixed(1) + ' m';

function stateOf(d) {
  const k = slot(S.day, d.id), hs = halves(S.half).map(h => k[h]);
  if (hs.some(v => v === 'me')) return 'mine';
  const mate = hs.find(v => v && MATE[v]);
  if (mate) return 'mate:' + mate;
  if (hs.every(v => v)) return 'taken';
  if (hs.some(v => v)) return 'half';
  return 'free';
}
function scores() {
  const anchors = [...S.near].map(id => present(MATE[id], S.day)).filter(Boolean);
  if (!anchors.length) return [];
  return DESKS.filter(d => freeFor(S.day, d.id, S.half) && passes(d))
    .map(d => ({ d, s: anchors.reduce((a, t) => a + Math.exp(-(dist(d, t) ** 2) / (2 * SIGMA * SIGMA)), 0) }))
    .sort((a, b) => b.s - a.s).slice(0, 3);
}

/* ── static plan ── */
function drawPlan() {
  const g = [];
  g.push('<defs><pattern id="abk-desks-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="6" height="6" fill="oklch(0.975 0.006 95)"/><path d="M0 0v6" stroke="oklch(0.26 0.03 255 / .22)" stroke-width="2"/></pattern>' +
    '<linearGradient id="abk-desks-halfg"><stop offset=".5" stop-color="oklch(0.88 0.01 255)"/><stop offset=".5" stop-color="oklch(0.995 0.003 95)"/></linearGradient>' +
    '<clipPath id="abk-desks-clip"><rect x="22" y="22" width="696" height="576" rx="6"/></clipPath><radialGradient id="abk-desks-heatg"><stop offset="0" stop-color="oklch(0.74 0.16 58)" stop-opacity=".62"/><stop offset=".55" stop-color="oklch(0.8 0.13 70)" stop-opacity=".24"/><stop offset="1" stop-color="oklch(0.85 0.1 80)" stop-opacity="0"/></radialGradient></defs>');
  g.push('<rect class="abk-desks-wall" x="22" y="22" width="696" height="576" rx="6"/>');
  g.push('<path class="abk-desks-win" d="M52 22h110M182 22h110M312 22h110M442 22h110M572 22h110M22 56v110M22 186v110M22 316v80"/>');
  g.push('<rect class="abk-desks-zone" x="44" y="414" width="318" height="162" rx="10"/><text class="abk-desks-lbl" x="58" y="436">Quiet zone</text>');
  g.push('<text class="abk-desks-lbl" x="470" y="232">Collab corner</text>');
  g.push('<rect class="abk-desks-core" x="386" y="414" width="104" height="184" rx="2"/><text class="abk-desks-lbl" x="438" y="510" text-anchor="middle">Core</text>');
  [['Larch', '8 seats', 512, 414, 206, 96], ['Rowan', '4 seats', 512, 510, 104, 88], ['Booth 1', '', 616, 510, 51, 88], ['Booth 2', '', 667, 510, 51, 88]].forEach(([n, st, x, y, w, h]) => {
    g.push('<rect class="abk-desks-room" x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '"/><text class="abk-desks-lbl2" x="' + (x + 10) + '" y="' + (y + 22) + '">' + (w < 60 ? n.replace('Booth ', 'B') : n) + '</text>' + (st ? '<text class="abk-desks-lbl" x="' + (x + 10) + '" y="' + (y + 40) + '">' + st + '</text>' : ''));
  });
  g.push('<rect class="abk-desks-room" x="618" y="236" width="100" height="150"/><text class="abk-desks-lbl2" x="630" y="260">Kitchen</text>');
  g.push('<g data-heat clip-path="url(#abk-desks-clip)"></g>');
  DESKS.forEach(d => {
    const chairY = d.r === 0 ? -9 : DH + 9;
    g.push('<g class="abk-desks-desk" data-id="' + d.id + '" role="button" tabindex="-1" transform="translate(' + d.x + ' ' + d.y + ')">' +
      '<circle class="abk-desks-chair" cx="' + DW / 2 + '" cy="' + chairY + '" r="7"/><rect class="abk-desks-top2" width="' + DW + '" height="' + DH + '" rx="4"/>' +
