css:
@property --abk-deposit-a { syntax: "<percentage>"; inherits: true; initial-value: 60%; }
@property --abk-deposit-b { syntax: "<percentage>"; inherits: true; initial-value: 85%; }

.abk-deposit {
  --abk-deposit-bg: oklch(0.965 0.013 80);
  --abk-deposit-ink: oklch(0.23 0.014 60);
  --abk-deposit-accent: oklch(0.6 0.17 38);
  --abk-deposit-full: oklch(0.64 0.09 150);
  --abk-deposit-half: oklch(0.8 0.13 78);
  --abk-deposit-none: oklch(0.6 0.17 32);
  --abk-deposit-paper: color-mix(in oklch, var(--abk-deposit-bg), white 60%);
  --abk-deposit-chitbg: color-mix(in oklch, var(--abk-deposit-bg), var(--abk-deposit-ink) 4%);
  --abk-deposit-line: color-mix(in oklch, var(--abk-deposit-ink) 11%, transparent);
  --abk-deposit-line2: color-mix(in oklch, var(--abk-deposit-ink) 20%, transparent);
  --abk-deposit-mute: color-mix(in oklch, var(--abk-deposit-ink) 57%, var(--abk-deposit-bg));
  --abk-deposit-tint: color-mix(in oklch, var(--abk-deposit-accent) 10%, var(--abk-deposit-paper));
  --abk-deposit-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-deposit-spring: linear(0, .1 6%, .38 13%, .74 21%, .97 29%, 1.07 36%, 1.08 43%, 1.04 53%, 1.005 66%, .997 80%, 1);
  --abk-deposit-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --abk-deposit-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-deposit-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-deposit;
  overflow: clip; isolation: isolate; border-radius: 16px; border: 1px solid var(--abk-deposit-line2);
  background: var(--abk-deposit-bg); color: var(--abk-deposit-ink);
  font: 14px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--abk-deposit-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & select, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-deposit-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }

  & .abk-deposit-app { height: 100%; display: grid; grid-template: "side main" minmax(0, 1fr) / 360px minmax(0, 1fr); }

  /* the chit */
  & .abk-deposit-side { grid-area: side; min-height: 0; padding: 18px 0 18px 18px; display: flex; }
  & .abk-deposit-chit { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 18px; padding: 24px 24px 22px; background: var(--abk-deposit-chitbg); border-radius: 14px 4px 4px 14px; position: relative;
    -webkit-mask: linear-gradient(#000 0 0) 0 0 / calc(100% - 8px) 100% no-repeat, radial-gradient(circle at 100% 50%, #0000 5px, #000 5.5px) 100% 0 / 8px 16px repeat-y;
    mask: linear-gradient(#000 0 0) 0 0 / calc(100% - 8px) 100% no-repeat, radial-gradient(circle at 100% 50%, #0000 5px, #000 5.5px) 100% 0 / 8px 16px repeat-y;
  }
  & .abk-deposit-brand { display: grid; gap: 4px; padding-bottom: 16px; border-bottom: 1.5px solid var(--abk-deposit-ink);
    & b { font: 600 clamp(30px, 3.4cqi, 38px)/.95 var(--abk-deposit-serif); letter-spacing: -.02em; }
    & b::first-letter { color: var(--abk-deposit-accent); }
    & span { font-size: 11px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--abk-deposit-mute); }
  }
  & .abk-deposit-sum { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: 9px 14px; font-size: 13.5px;
    & dt { color: var(--abk-deposit-mute); font-size: 12px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; padding-top: 1px; }
    & dd { margin: 0; text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }
    & dd small { display: block; font-weight: 450; font-size: 12px; color: var(--abk-deposit-mute); }
    & dd[data-empty] { color: var(--abk-deposit-mute); font-weight: 450; font-style: italic; }
    & .abk-deposit-due { grid-column: 1 / -1; display: flex; justify-content: space-between; align-items: baseline; padding-top: 12px; margin-top: 4px; border-top: 1px dashed var(--abk-deposit-line2); }
    & .abk-deposit-due span { font-size: 12px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--abk-deposit-mute); }
    & .abk-deposit-due output { font: 600 30px/1 var(--abk-deposit-serif); font-variant-numeric: tabular-nums lining-nums; }
  }
