/* Saltbridge Counter reservation with a deposit. The cancellation policy is drawn as a timeline from
   today to dinner; its two tier boundaries are registered @property percentages, so picking another
   date re-flows the gradient instead of jumping. Every refund figure comes from the same tiers. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const IC = {
  minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', left: '<path d="M15 5 8 12l7 7"/>', right: '<path d="m9 5 7 7-7 7"/>',
  arrow: '<path d="M5 12h14M13 6l6 6-6 6"/>', check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>',
  info: '<circle cx="12" cy="12" r="8.5"/><path d="M12 11v5M12 8v.2"/>', lock: '<rect x="5" y="10.5" width="14" height="10" rx="2"/><path d="M8 10.5V8a4 4 0 0 1 8 0v2.5"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

const NOW = new Date(2026, 9, 2, 10, 0);          /* Fri 2 Oct 2026, 10:00 */
const MENU = 145, DEPOSIT = 50, PAIRING = 85, SEATS = 12, H = 3600000, DAY = 24 * H;
const SITS = [['18:00', 18, 0], ['20:45', 20, 45]];
const MONTHS = [[2026, 9], [2026, 10], [2026, 11]];
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], WDL = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const MN = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'], MNL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const DIETS = ['Pescatarian', 'Vegetarian', 'No shellfish', 'No dairy', 'Gluten-free', 'No pork', 'No alcohol'];
const TIERS = [[168, 1, 'full refund', 'var(--abk-deposit-full)'], [48, .5, 'half back', 'var(--abk-deposit-half)'], [-Infinity, 0, 'no refund', 'var(--abk-deposit-none)']];
const dkey = d => d.getFullYear() + '-' + d.getMonth() + '-' + d.getDate();
const fmtDay = d => WD[d.getDay()] + ' ' + d.getDate() + ' ' + MN[d.getMonth()];
const fmtWhen = t => fmtDay(t) + ', ' + String(t.getHours()).padStart(2, '0') + ':' + String(t.getMinutes()).padStart(2, '0');

/* seats left per sitting: closed Mon and Tue, weekends nearly full */
