      let base = '880026114057393', chk = 0;
      while (!luhn(base + chk)) chk++;
      S.card = { name: S.card.name || 'Ana Reyes', num: (base + chk).replace(/(\d{4})(?=\d)/g, '$1 '), exp: '08/29', cvc: '417' };
      S.errors = {}; renderStep3($('[data-body]')); break;
    }
    case 'pay': pay(); break;
    case 'cal': toast('Added to calendar: Saltbridge Counter, ' + fmtWhen(dinnerAt())); break;
    case 'askcancel': S.confirmCancel = true; renderBody(); { const c = $('[data-act="keep"]'); if (c) c.focus(); } break;
    case 'keep': S.confirmCancel = false; renderBody(); break;
    case 'docancel': {
      const prev = { status: S.status, refund: S.refund };
      S.refund = Math.round(deposit() * tierAt(NOW)[1]); S.status = 'cancelled'; S.confirmCancel = false;
      render();
      toast('Cancelled · €' + S.refund + ' refunded', () => { S.status = prev.status; S.refund = prev.refund; render(); });
      break;
    }
    case 'again': S.status = 'draft'; S.step = 1; S.maxStep = 1; S.date = null; S.sit = null; S.refund = 0; S.card = { name: '', num: '', exp: '', cvc: '' }; render(); break;
    case 'sum': S.sumOpen = !S.sumOpen; $('.abk-deposit-app').toggleAttribute('data-sum', S.sumOpen); b.setAttribute('aria-expanded', String(S.sumOpen)); break;
    case 'undo': if (undoFn) { const f = undoFn; undoFn = null; f(); } $('.abk-deposit-toast').removeAttribute('data-open'); break;
  }
});
root.addEventListener('input', e => {
  const t = e.target;
  if (t.dataset.card) {
    const k = t.dataset.card;
    S.card[k] = k === 'name' ? t.value : formatInto(t, k);
    if (S.errors[k]) { delete S.errors[k]; t.removeAttribute('aria-invalid'); const em = t.parentElement.querySelector('em'); if (em) em.remove(); }
    return;
  }
  if (t.dataset.field) S[t.dataset.field] = t.value;
});
root.addEventListener('change', e => { if (e.target.dataset.field) { S[e.target.dataset.field] = e.target.value; renderSum(); } });
root.addEventListener('submit', e => { e.preventDefault(); pay(); });

/* the scrubber: drag, click the track, or use the keys */
const track = $('[data-track]'), thumb = $('[data-thumb]');
let dragging = false;
const scrubTo = x => { const r = track.getBoundingClientRect(); S.scrub = Math.max(0, Math.min(1, (x - r.left) / r.width)); renderPolicy(); };
track.addEventListener('pointerdown', e => {
  if (!dinnerAt()) return;
  dragging = true; thumb.setAttribute('data-drag', '');
  try { track.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointers cannot be captured */ }
  scrubTo(e.clientX);
});
track.addEventListener('pointermove', e => { if (dragging) scrubTo(e.clientX); });
const stop = () => { dragging = false; thumb.removeAttribute('data-drag'); };
track.addEventListener('pointerup', stop);
track.addEventListener('pointercancel', stop);
track.addEventListener('click', e => { if (dinnerAt()) { scrubTo(e.clientX); thumb.focus({ preventScroll: true }); } });
root.addEventListener('keydown', e => {
  if (e.target === thumb) {
    const d = dinnerAt();
    if (!d) return;
    const span = d - NOW, dayF = DAY / span;
    const step = { ArrowRight: dayF, ArrowUp: dayF, ArrowLeft: -dayF, ArrowDown: -dayF, PageUp: 7 * dayF, PageDown: -7 * dayF }[e.key];
    if (step != null) { e.preventDefault(); S.scrub = Math.max(0, Math.min(1, S.scrub + step)); renderPolicy(); }
    else if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); S.scrub = e.key === 'Home' ? 0 : 1; renderPolicy(); }
    return;
  }
  const day = e.target.closest && e.target.closest('.abk-deposit-day');
  if (day && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'PageUp', 'PageDown'].includes(e.key)) {
    e.preventDefault();
    if (e.key === 'PageUp' || e.key === 'PageDown') { const m = S.month + (e.key === 'PageDown' ? 1 : -1); if (m >= 0 && m < MONTHS.length) { S.month = m; render(); const f = $('.abk-deposit-day:not(:disabled)'); if (f) f.focus(); } return; }
    const delta = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key];
    let i = +day.dataset.d + delta, nx = null;
    while (!nx) { const c = $('.abk-deposit-day[data-d="' + i + '"]'); if (!c) break; if (!c.disabled) nx = c; else i += delta; }
    if (nx) { $$('.abk-deposit-day').forEach(c => { c.tabIndex = c === nx ? 0 : -1; }); nx.focus(); }
    return;
  }
  if (e.key === 'Escape' && S.sumOpen) { S.sumOpen = false; $('.abk-deposit-app').removeAttribute('data-sum'); $('[data-act="sum"]').setAttribute('aria-expanded', 'false'); }
});

render();

css:
.abk-scanner {
  --abk-scanner-bg: oklch(0.165 0.012 165);
  --abk-scanner-ink: oklch(0.95 0.012 160);
  --abk-scanner-ok: oklch(0.83 0.19 150);
  --abk-scanner-warn: oklch(0.84 0.15 82);
  --abk-scanner-bad: oklch(0.67 0.2 25);
  --abk-scanner-panel: color-mix(in oklch, var(--abk-scanner-bg), var(--abk-scanner-ink) 5%);
  --abk-scanner-raise: color-mix(in oklch, var(--abk-scanner-bg), var(--abk-scanner-ink) 10%);
  --abk-scanner-line: color-mix(in oklch, var(--abk-scanner-ink) 10%, transparent);
  --abk-scanner-line2: color-mix(in oklch, var(--abk-scanner-ink) 18%, transparent);
  --abk-scanner-mute: color-mix(in oklch, var(--abk-scanner-ink) 56%, var(--abk-scanner-bg));
  --abk-scanner-t-wk: oklch(0.76 0.12 195);
  --abk-scanner-t-sat: oklch(0.76 0.16 55);
  --abk-scanner-t-vip: oklch(0.86 0.13 92);
  --abk-scanner-t-sun: oklch(0.72 0.13 300);
  --abk-scanner-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-scanner-spring: linear(0, .1 6%, .38 13%, .74 21%, .97 29%, 1.07 36%, 1.08 43%, 1.04 53%, 1.005 66%, .997 80%, 1);
  --abk-scanner-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-scanner-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-scanner;
  overflow: clip; isolation: isolate; border-radius: 16px;
  background: var(--abk-scanner-bg); color: var(--abk-scanner-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--abk-scanner-ok);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; opacity: .38; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-scanner-ok); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--abk-scanner-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid currentColor; opacity: .6; }

  & .abk-scanner-app { height: 100%; display: grid; grid-template: "top top" auto "scan side" minmax(0, 1fr) / minmax(340px, 42%) minmax(0, 1fr); }

  & .abk-scanner-top { grid-area: top; display: flex; align-items: center; gap: 20px; padding: 12px 18px; border-bottom: 1px solid var(--abk-scanner-line); }
  & .abk-scanner-event { display: flex; align-items: center; gap: 12px; min-width: 0;
    & div { display: grid; line-height: 1.2; min-width: 0; }
    & b { font-size: 15px; font-weight: 750; letter-spacing: -.01em; }
    & span { font-size: 12px; color: var(--abk-scanner-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .abk-scanner-live { width: 10px; height: 10px; border-radius: 50%; background: var(--abk-scanner-ok); box-shadow: 0 0 0 0 var(--abk-scanner-ok); animation: abk-scanner-pulse 2s infinite; flex: none; }
  & .abk-scanner-count { margin-left: auto; display: flex; align-items: baseline; gap: 8px;
    & b { font: 700 26px/1 var(--abk-scanner-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
    & span { font-size: 12px; color: var(--abk-scanner-mute); }
    & i { font-style: normal; font-variant-numeric: tabular-nums; }
  }
  & .abk-scanner-clock { font: 600 14px var(--abk-scanner-mono); font-variant-numeric: tabular-nums; padding: 6px 10px; border-radius: 8px; background: var(--abk-scanner-panel); color: var(--abk-scanner-mute); }
  & .abk-scanner-views { display: none; }

  /* scanner column */
