  & .abk-scanner-vf { position: relative; min-height: 0; border-radius: 16px; overflow: hidden; background: #050807; cursor: pointer;
    & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
  }
  & .abk-scanner-reticle { position: absolute; inset: 0; pointer-events: none;
    & i { position: absolute; width: 34px; height: 34px; border: 3.5px solid var(--abk-scanner-rc, color-mix(in oklch, var(--abk-scanner-ink) 85%, transparent)); transition: border-color .25s; }
    & i[data-c="tl"] { left: var(--x0); top: var(--y0); border-right: 0; border-bottom: 0; border-top-left-radius: 12px; }
    & i[data-c="tr"] { right: var(--x0); top: var(--y0); border-left: 0; border-bottom: 0; border-top-right-radius: 12px; }
    & i[data-c="bl"] { left: var(--x0); bottom: var(--y0); border-right: 0; border-top: 0; border-bottom-left-radius: 12px; }
    & i[data-c="br"] { right: var(--x0); bottom: var(--y0); border-left: 0; border-top: 0; border-bottom-right-radius: 12px; }
  }
  & .abk-scanner-hint { position: absolute; left: 50%; bottom: 12px; translate: -50% 0; font-size: 12px; font-weight: 600; padding: 5px 12px; border-radius: 99px; background: rgb(0 0 0 / .55); color: var(--abk-scanner-ink); white-space: nowrap; transition: opacity .3s; }
  & .abk-scanner-result { min-height: 96px; border-radius: 14px; background: var(--abk-scanner-panel); border: 1px solid var(--abk-scanner-line); display: grid; grid-template-columns: 6px auto minmax(0, 1fr) auto; gap: 2px 14px; align-items: center; padding: 12px 14px 12px 0; overflow: hidden;
    & > i { grid-row: 1 / span 3; align-self: stretch; background: var(--c); border-radius: 0 4px 4px 0; }
    & .abk-scanner-badge { grid-row: 1 / span 3; width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center; background: color-mix(in oklch, var(--c) 18%, transparent); color: var(--c); }
    & .abk-scanner-badge svg { width: 26px; height: 26px; stroke-width: 2.4; }
    & strong, & b, & > span:not([class]) { grid-column: 3; min-width: 0; }
    & strong { font-size: 12px; font-weight: 800; letter-spacing: .14em; text-transform: uppercase; color: var(--c); }
    & b { font-size: 17px; font-weight: 700; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & span { font-size: 12.5px; color: var(--abk-scanner-mute); }
    & .abk-scanner-band { grid-row: 1 / span 3; grid-column: 4; display: grid; justify-items: center; gap: 4px; font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--abk-scanner-mute); }
    & .abk-scanner-band em { width: 40px; height: 12px; border-radius: 6px; background: var(--b); box-shadow: inset 0 -3px 0 rgb(0 0 0 / .2); }
    &[data-k] { animation: abk-scanner-flash .6s var(--abk-scanner-ease); }
    &[data-k] > * { animation: abk-scanner-in .4s var(--abk-scanner-ease) both; }
    &[data-k="idle"] { grid-template-columns: 1fr; padding: 12px 16px; color: var(--abk-scanner-mute); font-size: 13px; }
  }
  & .abk-scanner-ctrls { display: grid; grid-template-columns: 1fr auto auto; gap: 8px; }
  & .abk-scanner-go { height: 48px; border-radius: 13px; display: flex; align-items: center; justify-content: center; gap: 10px; font-weight: 750; font-size: 15px; background: var(--abk-scanner-ok); color: oklch(0.2 0.04 150); transition: transform .3s var(--abk-scanner-spring), filter .2s;
    & svg { width: 20px; height: 20px; stroke-width: 2.2; }
    &:hover:not(:disabled) { filter: brightness(1.08); }
    &:active:not(:disabled) { transform: scale(.97); }
    &:disabled { opacity: .5; }
  }
  & .abk-scanner-tool { height: 48px; padding: 0 14px; border-radius: 13px; display: flex; align-items: center; gap: 7px; font-size: 13px; font-weight: 650; background: var(--abk-scanner-raise);
    & svg { width: 18px; height: 18px; }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--abk-scanner-raise), var(--abk-scanner-ink) 8%); }
    &[aria-pressed="true"] { background: var(--abk-scanner-warn); color: oklch(0.22 0.05 80); }
  }

  /* side column */
