  & .abk-scanner-stats { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); gap: 12px; padding: 14px 16px 6px; }
  & .abk-scanner-chart { margin: 0; padding: 10px 12px 8px; border-radius: 12px; background: var(--abk-scanner-panel); display: grid; gap: 6px;
    & figcaption { display: flex; justify-content: space-between; align-items: baseline; font-size: 12px; }
