    & svg { width: 100%; height: 74px; overflow: visible; }
    & rect { fill: color-mix(in oklch, var(--abk-scanner-ok) 55%, transparent); transition: height .5s var(--abk-scanner-ease), y .5s var(--abk-scanner-ease); }
    & rect[data-now] { fill: var(--abk-scanner-ok); }
