    & dd { margin: 0; text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }
    & ol { margin: 0; padding: 0 0 0 16px; font-size: 12.5px; color: var(--abk-scanner-mute); display: grid; gap: 4px; }
  }
  & .abk-scanner-x { grid-row: span 2; width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; color: var(--abk-scanner-mute); & svg { width: 16px; height: 16px; } &:hover { background: var(--abk-scanner-raise); color: var(--abk-scanner-ink); } }
  & .abk-scanner-btn { height: 44px; border-radius: 12px; display: flex; align-items: center; justify-content: center; gap: 8px; font-weight: 700; font-size: 14px; background: var(--abk-scanner-ok); color: oklch(0.2 0.04 150); &:hover:not(:disabled) { filter: brightness(1.08); } &[data-tone="ghost"] { background: var(--abk-scanner-raise); color: var(--abk-scanner-ink); } }

  & .abk-scanner-toast { position: absolute; z-index: 40; left: 50%; bottom: 16px; padding: 10px 16px; border-radius: 12px; background: var(--abk-scanner-ink); color: var(--abk-scanner-bg); font-size: 13px; font-weight: 600; box-shadow: 0 14px 40px -12px rgb(0 0 0 / .6); max-width: calc(100% - 24px);
    translate: -50% 16px; opacity: 0; visibility: hidden; transition: translate .3s var(--abk-scanner-ease), opacity .2s, visibility 0s .3s;
