  @container abk-scanner (max-width: 759px) {
    & .abk-scanner-app { grid-template: "top" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
    & .abk-scanner-top { flex-wrap: wrap; gap: 8px 12px; padding: 10px 12px; }
    & .abk-scanner-count b { font-size: 20px; }
    & .abk-scanner-count span { display: none; }
    & .abk-scanner-views { display: flex; width: 100%; gap: 4px; padding: 3px; border-radius: 11px; background: var(--abk-scanner-panel);
      & button { flex: 1; height: 32px; border-radius: 8px; font-size: 13px; font-weight: 650; color: var(--abk-scanner-mute); }
      & button[aria-selected="true"] { background: var(--abk-scanner-raise); color: var(--abk-scanner-ink); }
    }
    & .abk-scanner-scan, & .abk-scanner-side { grid-area: main; border: 0; }
    & .abk-scanner-app:not([data-view="scan"]) .abk-scanner-scan, & .abk-scanner-app:not([data-view="list"]) .abk-scanner-side { display: none; }
    & .abk-scanner-scan { padding: 10px 12px 12px; }
    & .abk-scanner-stats { padding: 10px 12px 4px; }
    & .abk-scanner-types { grid-template-columns: 1fr 1fr; }
    & .abk-scanner-listhead { padding: 6px 12px 8px; }
    & .abk-scanner-row { grid-template-columns: 34px minmax(0, 1fr) 58px; & .abk-scanner-chip { display: none; } }
    & .abk-scanner-result b { font-size: 15px; }
    & .abk-scanner-result .abk-scanner-band { display: none; }
  }

  @media (prefers-reduced-motion: reduce) {
    & *, & *::before, & *::after { animation-duration: 1ms !important; animation-delay: 0s !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; transition-delay: 0s !important; }
  }
}

@keyframes abk-scanner-pulse { 0% { box-shadow: 0 0 0 0 color-mix(in oklch, oklch(0.83 0.19 150) 60%, transparent); } 70%, 100% { box-shadow: 0 0 0 9px transparent; } }
@keyframes abk-scanner-flash { from { background: color-mix(in oklch, var(--c, transparent) 30%, oklch(0.2 0.012 165)); } }
@keyframes abk-scanner-in { from { opacity: 0; translate: 0 6px; } }
@keyframes abk-scanner-fresh { from { background: color-mix(in oklch, oklch(0.83 0.19 150) 22%, transparent); } }

js:
/* Lowtide Weekender door scanner. The viewfinder is a DPR-aware canvas: each presented ticket draws a
   deterministic matrix code from its ID, and the reticle corners lock onto that code's box with the
   Web Animations API. The 2,150-guest list is windowed (only visible rows exist), and the arrival
   chart, type bars and gate total are all derived from one check-in log, so Undo rolls everything back. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const fmt = n => n.toLocaleString('en-GB');
const hms = s => [Math.floor(s / 3600), Math.floor(s / 60) % 60, s % 60].map(v => String(v).padStart(2, '0')).join(':');
const hm = s => hms(s).slice(0, 5);
const IC = {
  ok: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', warn: '<path d="M12 4 2.8 20h18.4L12 4Z"/><path d="M12 10v4.2M12 17.2v.3"/>', bad: '<circle cx="12" cy="12" r="8.5"/><path d="m8.5 8.5 7 7M15.5 8.5l-7 7"/>',
  x: '<path d="M6 6l12 12M18 6 6 18"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

/* ── data: 2,150 tickets ── */
const TYPES = {
  wk: { name: 'Weekend', band: 'Teal', c: 'var(--abk-scanner-t-wk)', n: 620, today: true },
  sat: { name: 'Saturday', band: 'Orange', c: 'var(--abk-scanner-t-sat)', n: 1240, today: true },
  vip: { name: 'VIP weekend', band: 'Gold', c: 'var(--abk-scanner-t-vip)', n: 80, today: true },
  sun: { name: 'Sunday', band: 'Violet', c: 'var(--abk-scanner-t-sun)', n: 210, today: false }
};
const FIRST = ['Ada', 'Bram', 'Chiara', 'Dev', 'Elif', 'Femi', 'Greta', 'Hugo', 'Ines', 'Jonah', 'Kaia', 'Luca', 'Maya', 'Nils', 'Omar', 'Paula', 'Quinn', 'Rosa', 'Sami', 'Tove', 'Uma', 'Vik', 'Wren', 'Xavi', 'Yara', 'Zeno', 'Aiko', 'Bea', 'Cato', 'Dara', 'Esme', 'Finn', 'Gil', 'Hana', 'Ivo', 'Jules', 'Kofi', 'Lena', 'Milo', 'Nora', 'Otto', 'Priya', 'Rafa', 'Sofia', 'Teo', 'Vera', 'Yusuf'];
const LAST = ['Mwangi', 'de Vries', 'Okoro', 'Lindqvist', 'Haddad', 'Moreau', 'Sato', 'Brennan', 'Kowalski', 'Ferreira', 'Nakamura', 'Abiola', 'Castillo', 'Petrov', 'Varga', 'Oyelaran', 'Whitfield', 'Delacroix', 'Tanaka', 'Grünewald', 'Achterberg', 'Carvalho', 'Demir', 'Holt', 'Lund', 'Raman', 'Aalto', 'Okafor', 'Whitlock', 'Fontaine', 'Brekke', 'Ito', 'Ramos', 'Novak', 'Quist', 'Ekström', 'Baptiste', 'Kimura', 'Adeyemi', 'Sørensen', 'Mbeki', 'Laine', 'Rossi'];
const DOORS = 17 * 3600;
const A = [];
(() => {
  const r = rng(2150);
  const types = Object.entries(TYPES).flatMap(([k, t]) => Array(t.n).fill(k));
  for (let i = types.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [types[i], types[j]] = [types[j], types[i]]; }
  types.forEach((type, i) => {
    const f = FIRST[Math.floor(r() * FIRST.length)], l = LAST[Math.floor(r() * LAST.length)];
    const code = 'LTW-' + (46656 + i * 7919 % 1632959).toString(36).toUpperCase().padStart(4, '0') + '-' + String(1000 + (i * 37) % 9000);
    const a = { i, name: f + ' ' + l, ini: f[0] + l.replace(/^de /, '')[0], type, code, inAt: null, gate: null, void: type === 'sat' && r() < .012, session: false };
    if (TYPES[type].today && !a.void && r() < (type === 'vip' ? .74 : .58)) { a.inAt = DOORS + Math.floor((1 - Math.pow(r(), 1.7)) * (2 * 3600 + 11 * 60)); a.gate = r() < .45 ? 'A' : 'B'; }
    A.push(a);
  });
})();
const S = { now: 19 * 3600 + 12 * 60, filter: 'recent', q: '', sel: null, log: [], last: null, torch: false, busy: false, view: 'scan', active: 0 };
const valid = a => TYPES[a.type].today && !a.void;
const expected = A.filter(valid).length;

/* the queue of people walking up to the gate */
const qr = rng(77);
function nextPresented() {
  const p = qr();
  const pick = f => { const pool = A.filter(f); return pool[Math.floor(qr() * pool.length)]; };
  if (p < .76) return pick(a => valid(a) && !a.inAt);
  if (p < .86) return pick(a => a.inAt);
  if (p < .94) return pick(a => a.type === 'sun');
  return pick(a => a.void) || pick(a => a.type === 'sun');
}

/* ── counters ── */
let shown = 0, tweenId = 0;
function renderCount() {
  const n = A.filter(a => a.inAt && valid(a)).length, el = $('[data-in]'), from = shown;
  $('[data-exp]').textContent = fmt(expected);
  cancelAnimationFrame(tweenId);
  if (RM.matches || from === 0) { el.textContent = fmt(n); shown = n; return; }
  const t0 = performance.now();
  const step = t => {
    if (!root.isConnected) return;
    const p = Math.min(1, (t - t0) / 450), v = Math.round(from + (n - from) * (1 - Math.pow(1 - p, 3)));
    el.textContent = fmt(v);
    if (p < 1) tweenId = requestAnimationFrame(step); else shown = n;
  };
  tweenId = requestAnimationFrame(step);
  shown = n;
}
function renderStats() {
  /* arrivals per 10 minutes since doors, the same log the gate total uses */
  const nb = Math.floor((S.now - DOORS) / 600) + 1, buckets = Array(nb).fill(0);
  A.forEach(a => { if (a.inAt && valid(a)) { const b = Math.floor((a.inAt - DOORS) / 600); if (b >= 0 && b < nb) buckets[b]++; } });
  const max = Math.max(...buckets, 10), w = 300 / nb;
  $('[data-chart]').innerHTML = '<line x1="0" x2="300" y1="20" y2="20"/>' + buckets.map((v, i) => { const h = v / max * 76; return '<rect x="' + (i * w + 1.5).toFixed(1) + '" y="' + (80 - h).toFixed(1) + '" width="' + (w - 3).toFixed(1) + '" height="' + h.toFixed(1) + '" rx="1.5"' + (i === nb - 1 ? ' data-now' : '') + '><title>' + hm(DOORS + i * 600) + ' · ' + v + '</title></rect>'; }).join('');
  /* labels sit exactly on the bucket they name */
  $('[data-axis]').innerHTML = [0, 4, 8, 12].filter(i => i / nb < .78).map(i => '<span style="left:' + (i / nb * 100).toFixed(2) + '%">' + hm(DOORS + i * 600) + '</span>').join('') + '<span style="right:0">now</span>';
  const last30 = A.filter(a => a.inAt && valid(a) && a.inAt > S.now - 1800).length;
  $('[data-rate]').textContent = Math.round(last30 / 3) + ' / 10 min lately';
  $('[data-types]').innerHTML = Object.entries(TYPES).map(([k, t]) => {
    const all = A.filter(a => a.type === k && !a.void), n = all.filter(a => a.inAt).length, voids = A.filter(a => a.type === k && a.void).length;
    return '<div style="--c:' + t.c + '"><span><b>' + t.name + '</b></span><span title="' + (voids ? voids + ' refunded tickets not counted' : '') + '">' + (t.today ? fmt(n) + ' / ' + fmt(all.length) : fmt(all.length) + ' · not valid today') + '</span><i><em style="--f:' + (t.today ? n / all.length : 0).toFixed(3) + '"></em></i></div>';
  }).join('');
}

/* ── list (windowed) ── */
const ROWH = 52;
let F = [], renderQueued = false;
function filtered() {
  const q = S.q.trim().toLowerCase();
  let list = A;
  if (q) list = list.filter(a => a.name.toLowerCase().includes(q) || a.code.toLowerCase().includes(q));
  if (S.filter === 'recent') list = list.filter(a => a.inAt).sort((x, y) => y.inAt - x.inAt);
  else if (S.filter === 'out') list = list.filter(a => valid(a) && !a.inAt).sort((x, y) => x.name.localeCompare(y.name));
  else if (S.filter === 'issues') list = list.filter(a => !valid(a)).sort((x, y) => x.name.localeCompare(y.name));
  else list = list.slice().sort((x, y) => x.name.localeCompare(y.name));
  return list;
}
function renderFilters() {
  const q = S.q.trim().toLowerCase(), base = q ? A.filter(a => a.name.toLowerCase().includes(q) || a.code.toLowerCase().includes(q)) : A;
  const counts = { recent: base.filter(a => a.inAt).length, all: base.length, out: base.filter(a => valid(a) && !a.inAt).length, issues: base.filter(a => !valid(a)).length };
  $('[data-filters]').innerHTML = [['recent', 'In'], ['out', 'Not in'], ['issues', 'Issues'], ['all', 'All']].map(([k, l]) => '<button type="button" role="tab" data-f="' + k + '" aria-selected="' + (S.filter === k) + '">' + l + ' <i>' + fmt(counts[k]) + '</i></button>').join('');
}
function refreshList(keepScroll) {
  F = filtered();
  const box = $('[data-list]');
  $('[data-spacer]').style.height = Math.max(F.length * ROWH, 1) + 'px';
  if (!keepScroll) box.scrollTop = 0;
  S.active = Math.min(S.active, Math.max(0, F.length - 1));
  paintRows();
  renderFilters();
}
function paintRows() {
  renderQueued = false;
  const box = $('[data-list]'), rows = $('[data-rows]');
  if (!F.length) { rows.innerHTML = '<p class="abk-scanner-empty">' + (S.q ? 'No guest or ticket matches “' + esc(S.q) + '”.' : 'Nobody here yet.') + '</p>'; rows.style.transform = ''; return; }
  const top = box.scrollTop, h = box.clientHeight || 400;
  const a = Math.max(0, Math.floor(top / ROWH) - 6), b = Math.min(F.length, Math.ceil((top + h) / ROWH) + 6);
  const q = S.q.trim();
  const mark = t => q ? esc(t).replace(new RegExp('(' + q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'ig'), '<mark>$1</mark>') : esc(t);
  let html = '';
  for (let k = a; k < b; k++) {
    const x = F[k], t = TYPES[x.type];
    const status = x.void ? '<time data-k="bad">refunded</time>' : !t.today ? '<time data-k="bad">Sunday</time>' : x.inAt ? '<time>' + hm(x.inAt) + '</time>' : '<time data-k="no">—</time>';
    html += '<button type="button" class="abk-scanner-row" role="listitem" data-a="' + x.i + '" data-k="' + k + '" style="--c:' + t.c + '"' + (S.sel === x.i ? ' aria-current="true"' : '') + (S.fresh === x.i ? ' data-fresh' : '') + ' tabindex="' + (k === S.active ? 0 : -1) + '">' +
      '<span class="abk-scanner-av">' + x.ini + '</span><div><b>' + mark(x.name) + '</b><small>' + mark(x.code) + '</small></div><span class="abk-scanner-chip">' + t.name + '</span>' + status + '</button>';
  }
  rows.innerHTML = html;
  rows.style.transform = 'translateY(' + a * ROWH + 'px)';
}
$('[data-list]').addEventListener('scroll', () => { if (!renderQueued) { renderQueued = true; requestAnimationFrame(() => { if (!root.isConnected) return; paintRows(); }); } });

function openDrawer(i) {
  const a = A[i], t = TYPES[a.type], d = $('[data-drawer]');
  S.sel = i;
  const state = a.void ? 'Refunded on 28 Sep · do not admit' : !t.today ? 'Sunday ticket · not valid today' : a.inAt ? 'In since ' + hms(a.inAt) + ' · Gate ' + a.gate : 'Not checked in';
  const hist = [];
  hist.push('Ticket issued ' + (3 + i % 20) + ' Aug');
  if (a.void) hist.push('Refunded 28 Sep (illness)');
  if (a.inAt) hist.push('Admitted ' + hms(a.inAt) + ' at Gate ' + a.gate + (a.session ? ' by you' : ''));
  d.innerHTML = '<header style="--c:' + t.c + '"><span class="abk-scanner-av">' + a.ini + '</span><b>' + esc(a.name) + '</b><button type="button" class="abk-scanner-x" data-act="close" aria-label="Close guest details">' + svg('x') + '</button><small>' + a.code + '</small></header>' +
    '<dl><dt>Ticket</dt><dd>' + t.name + '</dd><dt>Wristband</dt><dd>' + t.band + '</dd><dt>Status</dt><dd>' + state + '</dd></dl><ol>' + hist.map(h => '<li>' + h + '</li>').join('') + '</ol>' +
    (valid(a) ? (a.inAt ? '<button type="button" class="abk-scanner-btn" data-tone="ghost" data-act="uncheck">Undo check-in</button>' : '<button type="button" class="abk-scanner-btn" data-act="manual">Check in manually</button>')
      : '<p style="font-size:12.5px;color:var(--abk-scanner-mute)">Send ' + esc(a.name.split(' ')[0]) + ' to the box office at Gate A; staff there can upgrade or re-issue.</p>');
  d.setAttribute('data-open', '');
  paintRows();
  setTimeout(() => { const b = $('.abk-scanner-btn', d) || $('.abk-scanner-x', d); if (b) b.focus({ preventScroll: true }); }, 40);
}
function closeDrawer() { $('[data-drawer]').removeAttribute('data-open'); const was = S.sel; S.sel = null; paintRows(); const r = $('.abk-scanner-row[data-a="' + was + '"]'); if (r) r.focus({ preventScroll: true }); }

/* ── check-in log ── */
function admit(a, how) {
  a.inAt = S.now; a.gate = 'B'; a.session = true;
  S.log.push({ i: a.i, how });
  S.fresh = a.i;
  afterChange();
}
function undo() {
  const e = S.log.pop();
  if (!e) { toast('Nothing to undo at this gate yet'); return; }
  const a = A[e.i];
  a.inAt = null; a.gate = null; a.session = false;
  afterChange();
  toast('Undid ' + a.name + '’s check-in');
  if ($('[data-drawer]').hasAttribute('data-open') && S.sel === a.i) openDrawer(a.i);
}
function afterChange() {
  renderCount(); renderStats(); refreshList(true);
  const u = $('[data-act="undo"]');
  u.disabled = !S.log.length; u.title = S.log.length ? 'Undo last check-in (U)' : 'Nothing to undo at this gate yet';
}

/* ── scan: present, lock on, decide ── */
function decide(a) {
  if (a.void) return { k: 'bad', title: 'Do not admit', line: 'Refunded on 28 Sep', icon: 'bad', c: 'var(--abk-scanner-bad)' };
  if (!TYPES[a.type].today) return { k: 'bad', title: 'Wrong day', line: 'Sunday ticket · direct to the box office', icon: 'bad', c: 'var(--abk-scanner-bad)' };
  if (a.inAt) return { k: 'warn', title: 'Already in', line: 'Since ' + hm(a.inAt) + ' at Gate ' + a.gate + ' · check ID', icon: 'warn', c: 'var(--abk-scanner-warn)' };
  return { k: 'ok', title: 'Admit 1', line: TYPES[a.type].name + ' · ' + a.code, icon: 'ok', c: 'var(--abk-scanner-ok)' };
}
function showResult(a, r) {
  const t = TYPES[a.type], box = $('[data-result]');
  box.dataset.k = r.k;
  box.style.setProperty('--c', r.c);
  box.innerHTML = '<i></i><span class="abk-scanner-badge">' + svg(r.icon) + '</span><strong>' + r.title + '</strong><b>' + esc(a.name) + '</b><span>' + r.line + '</span>' +
    '<span class="abk-scanner-band" style="--b:' + t.c + '"><em></em>' + t.band + '</span>';
}
function scan(instant) {
  if (S.busy) return;
  const a = nextPresented();
  if (!a) return;
  S.busy = true;
  S.present = { a, t0: performance.now() - (instant ? 2000 : 0), locked: false };
  $('[data-hint]').style.opacity = 0;
  const btn = $('[data-act="scan"]');
  btn.disabled = true;
  reticle(null);
  const finish = () => {
    if (!root.isConnected) return;
    const r = decide(a);
    if (r.k === 'ok') admit(a, 'scan');
    showResult(a, r);
    reticle(r.c);
    S.busy = false; btn.disabled = false;
    S.now += 9 + Math.floor(qr() * 14);
    kick();
  };
  if (instant || RM.matches) { lockOn(true); finish(); }
  else { setTimeout(() => { if (root.isConnected) lockOn(false); }, 430); setTimeout(finish, 780); }
  kick();
}

/* ── viewfinder canvas ── */
const cv = $('[data-canvas]'), ctx = cv.getContext('2d'), vf = $('[data-vf]');
let cw = 0, ch = 0, dpr = 1, raf = 0, onScreen = true;
const noise = document.createElement('canvas');
noise.width = noise.height = 128;
(() => { const g = noise.getContext('2d'), im = g.createImageData(128, 128), r = rng(9); for (let p = 0; p < im.data.length; p += 4) { const v = r() * 255; im.data[p] = im.data[p + 1] = im.data[p + 2] = v; im.data[p + 3] = 255; } g.putImageData(im, 0, 0); })();
const LIGHTS = Array.from({ length: 7 }, (_, i) => { const r = rng(300 + i); return { x: r(), y: r() * .7, s: .12 + r() * .2, h: [40, 60, 200, 320, 150][i % 5], sp: .3 + r() * .5 }; });
function codeMatrix(i) {
  const N = 21, m = [], r = rng(i * 131 + 7);
  for (let y = 0; y < N; y++) { m.push([]); for (let x = 0; x < N; x++) m[y].push(r() < .5); }
  const finder = (ox, oy) => { for (let y = -1; y < 8; y++) for (let x = -1; x < 8; x++) { const X = ox + x, Y = oy + y; if (X < 0 || Y < 0 || X >= N || Y >= N) continue; const ring = Math.max(Math.abs(x - 3), Math.abs(y - 3)); m[Y][X] = ring !== 2 && ring !== 4; } };
  finder(0, 0); finder(N - 7, 0); finder(0, N - 7);
  for (let k = 8; k < N - 8; k++) { m[6][k] = k % 2 === 0; m[k][6] = k % 2 === 0; }
  return m;
}
let codeCache = { i: -1, m: null };
function geometry(now) {
  const p = S.present;
  if (!p) return null;
  const e = Math.min(1, (now - p.t0) / 430), ease = 1 - Math.pow(1 - e, 3);
  const size = Math.min(cw, ch) * .5;
  return { cx: cw / 2, cy: ch / 2 + (1 - ease) * ch * .65, rot: (1 - ease) * .22 + .045, scale: .86 + .14 * ease, size };
}
function drawFrame(now) {
  const w = cw, h = ch, T = now / 1000;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = '#060a09'; ctx.fillRect(0, 0, w, h);
  /* out-of-focus crowd lights */
  ctx.globalCompositeOperation = 'lighter';
  LIGHTS.forEach(l => {
    const x = (l.x + Math.sin(T * l.sp + l.h) * .03) * w, y = (l.y + Math.cos(T * l.sp * .7) * .02) * h, r = l.s * Math.max(w, h);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'oklch(0.55 0.12 ' + l.h + ' / ' + (S.torch ? .22 : .32) + ')'); g.addColorStop(1, 'oklch(0.3 0.05 ' + l.h + ' / 0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
  });
  ctx.globalCompositeOperation = 'source-over';
  if (S.torch) { const g = ctx.createRadialGradient(w / 2, h / 2, 0, w / 2, h / 2, Math.max(w, h) * .6); g.addColorStop(0, 'rgb(255 250 235 / .28)'); g.addColorStop(1, 'rgb(255 250 235 / 0)'); ctx.fillStyle = g; ctx.fillRect(0, 0, w, h); }
  /* the phone with its code */
  const G = geometry(now);
  if (G) {
    const a = S.present.a;
    if (codeCache.i !== a.i) codeCache = { i: a.i, m: codeMatrix(a.i) };
    const s = G.size, pw = s * 1.22, ph = s * 2.05;
    ctx.save();
    ctx.translate(G.cx, G.cy); ctx.rotate(G.rot); ctx.scale(G.scale, G.scale);
    ctx.shadowColor = 'rgb(0 0 0 / .6)'; ctx.shadowBlur = 30; ctx.shadowOffsetY = 12;
