}

@keyframes abk-cues-in { from { opacity: 0; translate: 0 6px; } }
@keyframes abk-cues-fire { 30% { box-shadow: 0 0 0 10px color-mix(in oklch, oklch(0.63 0.2 27) 0%, transparent), 0 10px 26px -10px oklch(0.63 0.2 27); filter: brightness(1.4); } }
@keyframes abk-cues-blink { 50% { opacity: .2; } }

