/* Meridian Design Awards run of show. Projected start times are re-derived every second from actual GO
   times, planned lengths and fixed hard starts; the interval is flexible down to 15 minutes, so a late
   first half is absorbed before part two. Timeline blocks are placed in cqi of their track and moved
   with transform, so a reorder or a length change glides instead of jumping. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const IC = {
  up: '<path d="m6 15 6-6 6 6"/>', down: '<path d="m6 9 6 6 6-6"/>', minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>',
  skip: '<path d="m5 5 9 7-9 7V5ZM18 5v14"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>'
