const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const H = 3600;
const hms = s => { s = Math.round(s); return [Math.floor(s / H), Math.floor(s / 60) % 60, s % 60].map(v => String(v).padStart(2, '0')).join(':'); };
const hm = s => hms(s).slice(0, 5);
const mmss = s => { const a = Math.abs(Math.round(s)); return (s < 0 ? '−' : '') + Math.floor(a / 60) + ':' + String(a % 60).padStart(2, '0'); };
const delta = s => (s > 0 ? '+' : '') + mmss(s);
const T0 = 19 * H, SPAN = 3 * H + 45 * 60, CURFEW = 22 * H + 30 * 60;
const KIND = { award: 'Award', perf: 'Performance', talk: 'Speech', film: 'Film', tech: 'Technical', break: 'Interval' };
const DEPTS = ['LX', 'SND', 'VID', 'STG'];
const award = (id, t, name, seg) => ({ id, title: 'Award · ' + t, seg, k: 'award', dur: 420, note: 'Presenter ' + name + ' from SR; winner up from row C. Two-minute speech cap, play-off at 2:30.', calls: [['LX', 'Winner special on, follow spot 2 pickup'], ['SND', 'Envelope sting, mic 2 live'], ['VID', 'Nominee reel, then winner card'], ['STG', 'Trophy table SL, runner with plinth']] });
const C = [
  { id: 1, title: 'Doors · walk-in music', seg: 'Pre-show', k: 'tech', dur: 1800, note: 'Foyer doors at 19:00. Hold the house if the queue is still past the cloakroom at 19:25.', calls: [['SND', 'Walk-in playlist, house at 70 dB'], ['LX', 'House full, stage wash 20%']] },
  { id: 2, title: 'House to half · show call', seg: 'Part one', k: 'tech', dur: 30, note: 'Beginners call at 19:25. FOH clearance before the go.', calls: [['LX', 'LX 12: house to half over 5 s'], ['SND', 'Fade walk-in over 10 s']] },
  { id: 3, title: 'Opening film · Forty Years of Form', seg: 'Part one', k: 'film', dur: 180, note: 'Three-minute film, hard cut to black. Host walk-on is on the last frame.', calls: [['VID', 'VT 1 roll on clear'], ['SND', 'Film audio to PA'], ['LX', 'LX 13: house out']] },
  { id: 4, title: 'Host walk-on · Amara Quist', seg: 'Part one', k: 'talk', dur: 120, note: 'Amara enters DSR to the lectern. Script page 2.', calls: [['LX', 'LX 14: lectern special'], ['SND', 'Walk-on sting, mic 1 live'], ['STG', 'Lectern preset DSL']] },
  { id: 5, title: 'Welcome & housekeeping', seg: 'Part one', k: 'talk', dur: 360, note: 'Fire exits, the hashtag, the sponsors. Slides advance on Amara’s clicker.', calls: [['VID', 'Slides 1–6'], ['SND', 'Mic 1']] },
  award(6, 'Best Wayfinding System', 'Oskar Lind', 'Part one'),
  award(7, 'Best Type Family', 'Hana Kimura', 'Part one'),
  award(8, 'Emerging Studio', 'Tove Ekström', 'Part one'),
  { id: 9, title: 'Performance · Kestrel String Trio', seg: 'Part one', k: 'perf', dur: 480, note: 'Risers in under the nominee reel. Eight minutes, two pieces, no talking.', calls: [['STG', 'Trio risers in during VT'], ['SND', 'Three instrument mics, wedges on'], ['LX', 'LX 31: warm cyc']] },
  award(10, 'Best Packaging', 'Rafa Okonkwo', 'Part one'),
  award(11, 'Best Interactive Work', 'Priya Raman', 'Part one'),
  { id: 12, title: 'Interval', seg: 'Interval', k: 'break', dur: 1500, flex: 900, note: 'Flexible: shrinks down to 15 minutes so part two still starts at 20:50.', calls: [['LX', 'House to full'], ['SND', 'Interval playlist'], ['STG', 'Reset trophy table']] },
  { id: 13, title: 'House to half · part two', seg: 'Part two', k: 'tech', dur: 30, hard: 20 * H + 50 * 60, note: 'Fixed start: the broadcast partner joins live at 20:50.', calls: [['LX', 'LX 40: house to half'], ['SND', 'Fade interval playlist'], ['VID', 'Live feed on']] },
  { id: 14, title: 'Keynote · Ines Okonkwo-Hart', seg: 'Part two', k: 'talk', dur: 720, note: 'Twelve minutes with slides. Comfort monitor shows a countdown from 2:00.', calls: [['VID', 'Keynote deck, confidence monitor'], ['SND', 'Headset mic 3']] },
  award(15, 'Best Identity', 'Jonas Brekke', 'Part two'),
  award(16, 'Best Book Design', 'Léa Fontaine', 'Part two'),
  { ...award(17, 'Lifetime Contribution', 'Amara Quist', 'Part two'), dur: 600, note: 'Tribute film (3 min) then the award. Standing ovation likely: hold the play-off.' },
  { ...award(18, 'Grand Prix', 'Ines Okonkwo-Hart', 'Part two'), dur: 480 },
  { id: 19, title: 'Closing & thank-yous', seg: 'Part two', k: 'talk', dur: 240, note: 'All winners on stage for the photo. Confetti on the last line.', calls: [['STG', 'All winners on, photo marks'], ['LX', 'LX 58: full stage'], ['SND', 'Play-out track']] },
  { id: 20, title: 'Afterparty in the foyer', seg: 'After', k: 'perf', dur: 3000, note: 'DJ in the foyer. Hard curfew at 22:30: bar shuts at 22:15.', calls: [['SND', 'Foyer DJ feed'], ['LX', 'House to full, foyer cue 3']] }
];
/* planned schedule, then what actually happened up to cue 10 */
(() => { let t = T0; C.forEach(c => { if (c.hard) t = Math.max(t, c.hard); c.plan = t; t += c.dur; }); })();
const ACTUAL = [[19 * H, 1870], [19 * H + 31 * 60 + 10, 40], [0, 180], [0, 145], [0, 400], [0, 435], [0, 390], [0, 425], [0, 475]];
(() => { let t = 0; ACTUAL.forEach(([s, d], i) => { const c = C[i]; c.start = s || t; c.ran = d; c.state = 'done'; t = c.start + d; }); C[9].start = t; C[9].state = 'live'; })();

const S = { now: C[9].start + 210, sel: 11, depts: new Set() };
let undoStack = [], toastT = 0, undoFn = null;
const live = () => C.find(c => c.state === 'live');
const nextUp = () => { const i = C.indexOf(live()); return C.slice(i + 1).find(c => !c.skip); };

/* every cue's projected start and length from the facts we have */
function project() {
  let t = null;
  const out = new Map();
  C.forEach((c, i) => {
    if (c.state === 'done') { out.set(c.id, { s: c.start, d: c.ran }); return; }
    if (c.state === 'live') { const el = S.now - c.start; out.set(c.id, { s: c.start, d: Math.max(c.dur, el), el }); t = c.start + Math.max(c.dur, el); return; }
    if (c.skip) { out.set(c.id, { s: t, d: 0, skip: true }); return; }
    let s = t == null ? c.plan : t;
    if (c.hard) s = Math.max(s, c.hard);
    let d = c.dur;
    /* a flexible cue (the interval) stretches or shrinks, down to its minimum, to meet the next hard start */
    if (c.flex) { const nx = C.slice(i + 1).find(x => !x.skip); if (nx && nx.hard) d = Math.max(c.flex, nx.hard - s); }
    out.set(c.id, { s, d });
    t = s + d;
  });
  return out;
}

/* ── render ── */
function rowHTML(c, P) {
  const p = P.get(c.id), st = c.state || (c.skip ? 'skip' : (nextUp() === c ? 'next' : 'up'));
  const dv = p.s - c.plan;
  const dl = c.state === 'live' ? p.el : null;
  const calls = c.calls.map(x => '<i' + (S.depts.has(x[0]) ? ' data-on' : '') + '>' + x[0] + '</i>').join('');
  const dim = S.depts.size && !c.calls.some(x => S.depts.has(x[0]));
  return '<li><button type="button" class="abk-cues-row" data-id="' + c.id + '" data-s="' + (c.skip && !c.state ? 'skip' : st) + '"' + (dim ? ' data-dim' : '') + (S.sel === c.id ? ' aria-current="true"' : '') + ' style="--k:var(--abk-cues-k-' + c.k + ')">' +
    '<span class="abk-cues-n">' + c.id + '</span><span class="abk-cues-t">' + hm(c.plan) + '</span>' +
    '<span class="abk-cues-p" data-p="' + c.id + '">' + projHTML(c, p) + '</span>' +
    '<span class="abk-cues-d" data-d="' + c.id + '">' + mmss(c.state === 'done' ? c.ran : c.state === 'live' ? c.dur : p.d || c.dur) + '</span>' +
    '<span class="abk-cues-c"><b>' + c.title + (c.hard ? '<span class="abk-cues-pin" title="Hard start ' + hm(c.hard) + '"></span>' : '') + '</b><small>' + c.seg + (c.flex ? ' · flexible' : '') + '</small></span>' +
    '<span class="abk-cues-calls">' + calls + '</span>' +
    (c.state === 'live' ? '<span class="abk-cues-live" data-live>' + mmss(dl) + ' / ' + mmss(c.dur) + '</span><span class="abk-cues-prog" data-prog><i></i></span>' : '') + '</button></li>';
}
function projHTML(c, p) {
  if (p.skip) return '—';
  const dv = Math.round(p.s - c.plan);
  return hms(p.s).slice(0, c.state === 'done' ? 8 : 5) + (Math.abs(dv) >= 5 ? '<small' + (dv < 0 ? ' data-k="early"' : '') + '>' + delta(dv) + '</small>' : '');
}
function renderList() {
  const P = project();
  $('[data-list]').innerHTML = C.map(c => rowHTML(c, P)).join('');
  renderTimeline(P, true);
  tick(true);
}
function renderTimeline(P, rebuild) {
  const track = $('[data-track]');
  if (rebuild || !track.children.length) {
    track.innerHTML = C.map(c => '<span class="abk-cues-blk" data-b="' + c.id + '" data-k="' + c.k + '" style="--k:var(--abk-cues-k-' + c.k + ')" title="' + c.id + ' · ' + c.title + '"></span>').join('') +
      '<span class="abk-cues-mark" data-k="curfew" style="--x:' + ((CURFEW - T0) / SPAN).toFixed(4) + '"></span><span class="abk-cues-mark" data-k="end" data-end></span><span class="abk-cues-mark" data-k="now" data-now></span>';
    $('[data-axis]').innerHTML = [0, 1, 2, 3, 4, 5, 6, 7].map(k => { const t = T0 + k * 1800; return '<span style="left:' + ((t - T0) / SPAN * 100).toFixed(2) + '%">' + hm(t) + '</span>'; }).join('');
  }
  C.forEach(c => {
    const b = $('[data-b="' + c.id + '"]', track), p = P.get(c.id);
    if (!b || !p) return;
    b.style.setProperty('--x', ((p.s - T0) / SPAN).toFixed(4));
    b.style.setProperty('--w', ((p.d || 0) / SPAN).toFixed(4));
    b.dataset.s = c.state || (c.skip ? 'skip' : 'up');
    if (S.sel === c.id) b.setAttribute('aria-current', 'true'); else b.removeAttribute('aria-current');
  });
  const last = [...C].reverse().find(c => !c.skip), lp = P.get(last.id);
  $('[data-end]').style.setProperty('--x', ((lp.s + lp.d - T0) / SPAN).toFixed(4));
  $('[data-now]').style.setProperty('--x', ((S.now - T0) / SPAN).toFixed(4));
}
let lastText = new Map();
function setText(el, html) { if (el && lastText.get(el) !== html) { lastText.set(el, html); el.innerHTML = html; } }
function tick(force) {
  const P = project(), L = live();
  $('[data-clock]').textContent = hms(S.now);
  C.forEach(c => { if (c.state !== 'done') setText($('[data-p="' + c.id + '"]'), projHTML(c, P.get(c.id))); });
  if (L) {
    const el = S.now - L.start, prog = $('[data-prog]');
    setText($('[data-live]'), mmss(el) + ' / ' + mmss(L.dur));
    if (prog) { prog.style.setProperty('--p', Math.min(1, el / L.dur).toFixed(4)); prog.toggleAttribute('data-over', el > L.dur); }
  }
  /* drift: how late the next cue will go against its plan */
  const nx = nextUp(), np = nx ? P.get(nx.id) : null, dr = np ? np.s - nx.plan : L ? L.start - L.plan : 0;
  const after = C.find(c => c.hard && !c.state && !c.skip), ap = after ? P.get(after.id) : null;
  const d = $('[data-drift]');
  d.dataset.k = Math.abs(dr) < 30 ? 'ok' : dr > 0 ? 'late' : 'ok';
  setText(d, '<small>' + (dr >= 30 ? 'Running late' : dr <= -30 ? 'Running early' : 'On time') + '</small><b>' + delta(Math.round(dr)) + '</b>' + (ap && dr > 0 ? '<small style="letter-spacing:.04em;text-transform:none">' + (ap.s <= after.hard ? 'interval absorbs it' : 'part two late ' + delta(ap.s - after.hard)) + '</small>' : ''));
  const last = [...C].reverse().find(c => !c.skip), lp = P.get(last.id), end = lp.s + lp.d, over = end - CURFEW;
  const cf = $('[data-curfew]');
  cf.dataset.k = over > 0 ? 'over' : 'ok';
  setText(cf, '<small>' + (over > 0 ? 'Over curfew' : 'Ends · curfew 22:30') + '</small><b>' + (over > 0 ? delta(over) : hm(end)) + '</b>');
  setText($('[data-gonext]'), nx ? nx.id + ' · ' + nx.title : 'End of show');
  $('[data-act="go"]').disabled = !L;
  renderTimeline(P, false);
  if (force) renderSide(P);
  else updateSideTimes(P);
}
function updateSideTimes(P) {
