root.addEventListener('click', e => {
  const b = e.target.closest('button, .abk-cues-blk');
  if (!b || !root.contains(b)) return;
  if (b.dataset.b) { select(+b.dataset.b); return; }
  if (b.dataset.id && b.classList.contains('abk-cues-row')) { select(+b.dataset.id); return; }
  if (b.dataset.dept) {
    const d = b.dataset.dept;
    S.depts.has(d) ? S.depts.delete(d) : S.depts.add(d);
