  if ((e.key === ' ' && onGoTarget) || ((e.key === 'g' || e.key === 'G') && !e.metaKey && !e.ctrlKey)) { e.preventDefault(); go(); return; }
  if ((e.metaKey || e.ctrlKey) && (e.key === 'z' || e.key === 'Z')) { e.preventDefault(); act('undo'); return; }
