css:
.abk-rsvp {
  --abk-rsvp-bg: oklch(0.982 0.006 95);
  --abk-rsvp-ink: oklch(0.24 0.02 60);
  --abk-rsvp-accent: oklch(0.52 0.1 128);
  --abk-rsvp-no: oklch(0.58 0.13 30);
  --abk-rsvp-wait: oklch(0.78 0.11 80);
  --abk-rsvp-paper: oklch(1 0 none);
  --abk-rsvp-line: color-mix(in oklch, var(--abk-rsvp-ink) 9%, transparent);
  --abk-rsvp-line2: color-mix(in oklch, var(--abk-rsvp-ink) 17%, transparent);
  --abk-rsvp-mute: color-mix(in oklch, var(--abk-rsvp-ink) 55%, var(--abk-rsvp-bg));
  --abk-rsvp-soft: color-mix(in oklch, var(--abk-rsvp-ink) 4%, var(--abk-rsvp-bg));
  --abk-rsvp-tint: color-mix(in oklch, var(--abk-rsvp-accent) 11%, var(--abk-rsvp-paper));
  --abk-rsvp-m-beef: oklch(0.55 0.12 30);
  --abk-rsvp-m-fish: oklch(0.6 0.09 225);
  --abk-rsvp-m-veg: oklch(0.6 0.12 135);
  --abk-rsvp-m-kids: oklch(0.75 0.12 80);
  --abk-rsvp-m-none: oklch(0.8 0.01 80);
  --abk-rsvp-ease: cubic-bezier(.2, .8, .2, 1);
  --abk-rsvp-spring: linear(0, .1 6%, .38 13%, .74 21%, .97 29%, 1.07 36%, 1.08 43%, 1.04 53%, 1.005 66%, .997 80%, 1);
  --abk-rsvp-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --abk-rsvp-mono: ui-monospace, Menlo, Consolas, monospace;
  position: relative; width: 100%; height: var(--abk-rsvp-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: abk-rsvp;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--abk-rsvp-line2);
  background: var(--abk-rsvp-bg); color: var(--abk-rsvp-ink);
  font: 13.5px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--abk-rsvp-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button, & input, & textarea, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled, & button[aria-disabled="true"] { cursor: not-allowed; opacity: .4; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & :focus-visible { outline: 2px solid var(--abk-rsvp-accent); outline-offset: 2px; }
  & [hidden] { display: none !important; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--abk-rsvp-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--abk-rsvp-line2); border-bottom-width: 2px; color: var(--abk-rsvp-mute); background: var(--abk-rsvp-paper); }

  & .abk-rsvp-app { position: relative; height: 100%; display: grid; grid-template: "top top top" auto "nav main side" minmax(0, 1fr) / 196px minmax(0, 1fr) 292px; }

  & .abk-rsvp-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 12px 16px; border-bottom: 1px solid var(--abk-rsvp-line2); }
  & .abk-rsvp-title { display: grid; line-height: 1.1; margin-right: auto; min-width: 0;
    & b { font: 500 clamp(21px, 2.2cqi, 26px)/1 var(--abk-rsvp-serif); letter-spacing: -.01em; }
    & b i { color: var(--abk-rsvp-accent); }
    & span { font-size: 12px; color: var(--abk-rsvp-mute); margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .abk-rsvp-deadline { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--abk-rsvp-mute); white-space: nowrap;
    & b { font: 600 16px var(--abk-rsvp-serif); color: var(--abk-rsvp-ink); font-variant-numeric: tabular-nums; }
  }
  & .abk-rsvp-search { display: flex; align-items: center; gap: 8px; height: 36px; width: min(240px, 24cqi); padding: 0 8px 0 11px; border-radius: 10px; background: var(--abk-rsvp-paper); border: 1px solid var(--abk-rsvp-line2);
    & svg { width: 15px; height: 15px; color: var(--abk-rsvp-mute); flex: none; }
    & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 13.5px; }
