  & .abk-rsvp-btn { height: 36px; padding: 0 13px 0 10px; border-radius: 10px; display: flex; align-items: center; gap: 7px; font-weight: 650; font-size: 13px; background: var(--abk-rsvp-accent); color: var(--abk-rsvp-paper); white-space: nowrap; transition: background .2s, transform .3s var(--abk-rsvp-spring);
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--abk-rsvp-accent) 85%, black); }
    &:active:not(:disabled) { transform: scale(.97); }
    &[data-tone="ghost"] { background: var(--abk-rsvp-paper); color: var(--abk-rsvp-ink); box-shadow: inset 0 0 0 1px var(--abk-rsvp-line2); }
    &[data-tone="ghost"]:hover { box-shadow: inset 0 0 0 1px var(--abk-rsvp-ink); background: var(--abk-rsvp-paper); }
    &[data-tone="ink"] { background: var(--abk-rsvp-ink); }
