  }
  & .abk-rsvp-seg { width: 100%; display: flex; align-items: center; gap: 9px; padding: 8px 10px; border-radius: 9px; text-align: left; font-weight: 550; transition: background .2s;
    & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c, var(--abk-rsvp-line2)); flex: none; }
    & output { margin-left: auto; font-size: 12px; font-weight: 650; color: var(--abk-rsvp-mute); font-variant-numeric: tabular-nums; }
    &:hover { background: var(--abk-rsvp-soft); }
    &[aria-selected="true"] { background: var(--abk-rsvp-paper); box-shadow: 0 1px 2px color-mix(in oklch, var(--abk-rsvp-ink) 12%, transparent), inset 0 0 0 1px var(--abk-rsvp-line); & output { color: var(--abk-rsvp-ink); } }
  }
  & .abk-rsvp-sides { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; padding: 3px; border-radius: 10px; background: var(--abk-rsvp-soft);
