    &[data-on] { grid-template-rows: 1fr; }
  }
  & .abk-rsvp-bulkbar { display: flex; align-items: center; gap: 6px; padding: 8px 12px; margin: 8px 12px 0; border-radius: 11px; background: var(--abk-rsvp-ink); color: var(--abk-rsvp-paper);
