  }
  & .abk-rsvp-add { grid-row: 2; display: grid; grid-template-columns: 1.4fr 1.2fr .9fr auto auto; gap: 8px; align-items: end; padding: 10px 12px; margin: 8px 12px 0; border-radius: 12px; background: var(--abk-rsvp-paper); border: 1px solid var(--abk-rsvp-line2); animation: abk-rsvp-in .3s var(--abk-rsvp-ease);
