    & .abk-rsvp-name mark { background: color-mix(in oklch, var(--abk-rsvp-wait) 50%, transparent); color: inherit; border-radius: 3px; }
    &:hover { background: color-mix(in oklch, var(--abk-rsvp-accent) 4%, transparent); }
    &[aria-selected="true"] { background: var(--abk-rsvp-tint); }
    &:focus-visible { outline-offset: -2px; border-radius: 6px; }
