  }
  & .abk-rsvp-check { width: 20px; height: 20px; border-radius: 6px; border: 1.5px solid var(--abk-rsvp-line2); background: var(--abk-rsvp-paper); display: grid; place-items: center; transition: background .2s, border-color .2s;
