    & .abk-rsvp-views { grid-area: views; display: flex; gap: 4px; padding: 8px 12px; border-top: 1px solid var(--abk-rsvp-line);
      & button { flex: 1; height: 32px; border-radius: 9px; font-size: 12.5px; font-weight: 650; color: var(--abk-rsvp-mute); }
      & button[aria-selected="true"] { background: var(--abk-rsvp-ink); color: var(--abk-rsvp-paper); }
    }
  }
  @container abk-rsvp (max-width: 759px) {
    & .abk-rsvp-app { grid-template: "top" auto "nav" auto "main" minmax(0, 1fr) "views" auto / minmax(0, 1fr); }
    & .abk-rsvp-top { flex-wrap: wrap; gap: 8px; padding: 10px 12px; }
    & .abk-rsvp-title { width: 100%; }
    & .abk-rsvp-search { flex: 1; width: auto; }
    & .abk-rsvp-nav { flex-direction: row; overflow-x: auto; padding: 8px 10px; border-right: 0; border-bottom: 1px solid var(--abk-rsvp-line); scrollbar-width: none; gap: 6px;
      & > div:first-child { display: flex; gap: 4px; }
      & h3, & .abk-rsvp-sides { display: none; }
    }
    & .abk-rsvp-seg { width: auto; white-space: nowrap; padding: 6px 10px; }
    & .abk-rsvp-cols { display: none; }
    & .abk-rsvp-row { grid-template-columns: 26px minmax(0, 1fr) auto; grid-template-areas: "c n s" "c m t"; row-gap: 4px;
      & > :nth-child(1) { grid-area: c; } & .abk-rsvp-name { grid-area: n; } & > :nth-child(3) { grid-area: s; justify-self: end; } & > :nth-child(4) { grid-area: m; } & > :nth-child(5) { grid-area: t; justify-self: end; }
    }
    & .abk-rsvp-add { grid-template-columns: 1fr 1fr; }
    & .abk-rsvp-keys { display: none; }
    & .abk-rsvp-compose { border: 0; }
  }

  @media (prefers-reduced-motion: reduce) {
    & *, & *::before, & *::after { animation-duration: 1ms !important; animation-delay: 0s !important; transition-duration: 1ms !important; transition-delay: 0s !important; }
    & .abk-rsvp-progress[data-run] i { width: 100%; }
  }
}

@keyframes abk-rsvp-in { from { opacity: 0; translate: 0 6px; } }
@keyframes abk-rsvp-flash { from { background: color-mix(in oklch, oklch(0.52 0.1 128) 22%, transparent); } }
@keyframes abk-rsvp-load { to { width: 100%; } }

js:
/* Ilse & Tomas guest list. One array of guests drives the segment counts, the headcount bar, the reply
   funnel and the meal bars, so a bulk edit is reflected everywhere at once and can be undone. The
   reminder composer paints {merge} fields on a mirror layer behind its textarea. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const IC = {
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>', dash: '<path d="M7 12h10"/>', chev: '<path d="m7 10 5 5 5-5"/>', x: '<path d="M6 6l12 12M18 6 6 18"/>',
  left: '<path d="M15 5 8 12l7 7"/>', right: '<path d="m9 5 7 7-7 7"/>', note: '<path d="M6 4h9l3 3v13H6z"/><path d="M9 11h6M9 15h4"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const rng = a => () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

const TODAY = '2 Oct', DEADLINE = 'Friday 23 October', DAYS_LEFT = 21, TABLES = 13, SEATS = 10;
const STATUS = { yes: ['Attending', 'var(--abk-rsvp-accent)'], no: ['Declined', 'var(--abk-rsvp-no)'], wait: ['Awaiting', 'var(--abk-rsvp-wait)'] };
const MEALS = { beef: ['Braised beef cheek', 'var(--abk-rsvp-m-beef)', 'Beef'], fish: ['Sea bream', 'var(--abk-rsvp-m-fish)', 'Bream'], veg: ['Squash risotto', 'var(--abk-rsvp-m-veg)', 'Risotto'], kids: ['Kids’ plate', 'var(--abk-rsvp-m-kids)', 'Kids'], none: ['Not chosen', 'var(--abk-rsvp-m-none)', 'Choose'] };
const SIDES = { I: 'Ilse', T: 'Tomas' };

/* ── guests, by household ── */
const SUR = ['Varga', 'Achterberg', 'Okafor', 'Lindqvist', 'Moreau', 'Haddad', 'Sato', 'Brennan', 'Kowalski', 'Ferreira', 'Nakamura', 'Castillo', 'Petrov', 'Whitfield', 'Delacroix', 'Tanaka', 'Carvalho', 'Demir', 'Holt', 'Raman', 'Aalto', 'Fontaine', 'Brekke', 'Ramos', 'Novak', 'Ekström', 'Baptiste', 'Kimura', 'Adeyemi', 'Sørensen', 'Mbeki', 'Laine', 'Rossi', 'Quist', 'Ito', 'Okonkwo', 'de Vries', 'Abiola', 'Grünewald', 'Oyelaran', 'Vos', 'Horvath', 'Bianchi'];
const FN = ['Márta', 'Gábor', 'Anneke', 'Joost', 'Ruth', 'Daniel', 'Freja', 'Elias', 'Camille', 'Hugo', 'Leila', 'Omar', 'Yui', 'Kenji', 'Siobhan', 'Cian', 'Agata', 'Piotr', 'Beatriz', 'Rui', 'Haruka', 'Lucía', 'Mateo', 'Irina', 'Pavel', 'Grace', 'Theo', 'Élise', 'Bastien', 'Mika', 'Inês', 'Tiago', 'Selin', 'Emre', 'Nora', 'Aarav', 'Anu', 'Juhani', 'Margaux', 'Sigrid', 'Lars', 'Mateus', 'Clara', 'Jonas', 'Wren', 'Felix'];
const KIDS = ['Lili', 'Bram', 'Noor', 'Otto', 'Ada', 'Milo', 'Zoe', 'Teo', 'Ivy', 'Leo'];
const CITY = ['Szeged', 'Utrecht', 'Lagos', 'Malmö', 'Lyon', 'Beirut', 'Osaka', 'Galway', 'Kraków', 'Porto', 'Kyoto', 'Seville', 'Sofia', 'Leeds', 'Brussels', 'Nagoya', 'Lisbon', 'Izmir', 'Bath', 'Pune', 'Turku', 'Nantes', 'Bergen', 'Bilbao', 'Brno', 'Uppsala', 'Montréal', 'Sapporo', 'Ibadan', 'Aarhus', 'Durban', 'Tampere', 'Bologna', 'Gothenburg', 'Kobe', 'Enugu', 'Haarlem', 'Accra', 'Leipzig', 'Abuja', 'Ghent', 'Pécs', 'Turin'];
const DIET = ['Coeliac', 'No nuts', 'Vegan', 'Lactose-free', 'Pregnant: no raw fish', 'Halal', 'No shellfish'];
const G = [], HH = [];
(() => {
  const r = rng(2111);
  let gid = 0, tbl = 1, seat = 0;
  SUR.forEach((sur, h) => {
    const size = h < 2 ? 4 : r() < .25 ? 1 : r() < .7 ? 2 : r() < .85 ? 3 : 4;
    const side = h === 0 ? 'I' : h === 1 ? 'T' : r() < .52 ? 'I' : 'T';
    const p = r(), hs = p < .64 ? 'yes' : p < .76 ? 'no' : 'wait';
    const house = { id: h, sur, city: CITY[h % CITY.length], side, code: sur.slice(0, 3).toUpperCase().replace(/[^A-Z]/g, 'X') + '-' + (h + 11), opened: hs !== 'wait' || r() < .45 };
    HH.push(house);
    for (let k = 0; k < size; k++) {
      const child = size >= 3 && k >= 2;
      const first = child ? KIDS[(h + k) % KIDS.length] : FN[(h * 2 + k * 7) % FN.length];
      let status = hs;
      if (hs === 'yes' && !child && size > 1 && r() < .08) status = 'no';
      const g = { id: ++gid, hh: h, first, last: sur, side, child, status, meal: null, diet: '', table: null, reminded: null };
      if (status === 'yes') {
        g.meal = child ? 'kids' : r() < .1 ? null : ['beef', 'fish', 'veg', 'beef', 'fish'][Math.floor(r() * 5)];
        if (!child && r() < .13) { g.diet = DIET[Math.floor(r() * DIET.length)]; if (g.diet === 'Vegan') g.meal = 'veg'; }
      }
      if (status === 'wait' && house.opened && r() < .5) g.reminded = '14 Sep';
      G.push(g);
    }
  });
  /* seat whole attending households, in order, until two tables are left free for late replies */
  HH.forEach(house => {
    const here = G.filter(g => g.hh === house.id && g.status === 'yes');
    if (!here.length || tbl > TABLES - 2) return;
    if (seat + here.length > SEATS) { tbl++; seat = 0; }
    if (tbl > TABLES - 2) return;
    if (house.id % 6 === 5) return;
    here.forEach(g => { g.table = tbl; }); seat += here.length;
  });
})();

const S = { seg: 'all', side: 'all', q: '', meal: null, sel: new Set(), focus: null, anchor: null, view: 'list', composeIx: 0 };
